(window.RAGHIB = window.RAGHIB || {})["2-4"] = [
  {"a": [100, 101], "h": "The three kinds of people who reject the truth — in two verses", "hAr": "أصناف دافعي الحقّ الثلاثة — في آيتين", "said": "وقد دل تعالى بالآيتين أن جل اليهود ثلاث فرق، فريق جاهر ونبذ العهد، وفريق لم يجاهروا بذلك، لكنهم لم يؤمنوا به، وهم أكثرهم، وفريق آخر طرحوا حكم الكتاب عنادا، فصاروا في حكم الجهلة، وهذه القسمة عجيبة الشأن، فإن دافعي الحق ثلاثة أقسام، جاهل غير عالم بجهله، وهو الشرير الذي لا مداواة له، وإياه عنى بقوله. ﴿أَوَكُلَّمَا عَٰهَدُواْ عَهۡدٗا نَّبَذَهُۥ فَرِيقٞ مِّنۡهُمۚ﴾، وجاهل عالم بجهله، وهو الشاك وإياه عنى بقوله: ﴿بَلۡ أَكۡثَرُهُمۡ لَا يُؤۡمِنُونَ﴾، ومعاند غير جاهل، وإياه عنى بقوله: ﴿نَبَذَ فَرِيقٞ مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا يَعۡلَمُونَ﴾", "en": "Ar-Raghib reads verses 100 and 101 together and finds in them a complete map. They describe three groups: one that openly threw away its covenant; a larger one that did not openly throw it away but still did not believe; and a group of the learned who cast the Book behind their backs out of stubbornness, and so became like the ignorant.\n\"This division is wonderful,\" he says, \"for everyone who pushes the truth away is one of three\": the ignorant man who does not know he is ignorant — the incurable one (\"a party of them threw it away\"); the ignorant man who knows he is ignorant — the doubter (\"most of them do not believe\"); and the stubborn man who is not ignorant at all (\"a party of those given the Book threw Allah's Book behind their backs, as if they did not know\"). Every rejecter of truth, in every age, falls into one of these three.", "ar": "قرأ الراغب الآيتين ١٠٠ و١٠١ معًا فوجد فيهما خريطةً كاملة: فرقةٌ جاهرت ونبذت العهد، وفرقةٌ — وهم أكثرهم — لم تجاهر لكنها لم تؤمن، وفرقةٌ من العلماء طرحت حكم الكتاب عنادًا فصارت في حكم الجهلة.\nقال: «وهذه القسمة عجيبة الشأن، فإن دافعي الحقّ ثلاثة أقسام»: جاهلٌ غير عالمٍ بجهله — وهو الشرّير الذي لا مداواة له —: ﴿أَوَكُلَّمَا عَٰهَدُواْ عَهۡدٗا نَّبَذَهُۥ فَرِيقٞ مِّنۡهُمۚ﴾؛ وجاهلٌ عالمٌ بجهله — وهو الشاكّ —: ﴿بَلۡ أَكۡثَرُهُمۡ لَا يُؤۡمِنُونَ﴾؛ ومعاندٌ غير جاهل: ﴿نَبَذَ فَرِيقٞ مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا يَعۡلَمُونَ﴾. وكلّ من دافع الحقّ في كلّ زمانٍ لا يخرج عن هذه الثلاثة.", "links": [{"ref": "2:100", "q": "﴿أَوَكُلَّمَا عَٰهَدُواْ عَهۡدٗا نَّبَذَهُۥ فَرِيقٞ مِّنۡهُمۚ﴾", "en": "The ignorant who does not know it — incurable", "ar": "الجاهل الذي لا يعلم جهله — لا دواء له"}, {"ref": "2:100", "q": "﴿بَلۡ أَكۡثَرُهُمۡ لَا يُؤۡمِنُونَ﴾", "en": "The ignorant who knows it — the doubter", "ar": "الجاهل العالم بجهله — الشاكّ"}, {"ref": "2:101", "q": "﴿نَبَذَ فَرِيقٞ مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا يَعۡلَمُونَ﴾", "en": "The stubborn who knows — and acts as if he did not", "ar": "المعاند العالم — يتصرّف كأنه لا يعلم"}], "v": 1, "p": 273, "pe": 273, "sid": 274},
  {"a": [102, 102], "h": "What sorcery is — three views, and the one he holds", "hAr": "ما السحر — ثلاثة أقوال، والقول الذي اختاره", "said": "وأما السحر فقد اختلف في مائيته على ثلاثة أوجه ... فالأول: ما ذهب إليه أكثر الجدليين، وهو أنه اسم خداع وتخييلات لا حقيقة له ... والثاني ما ذهب إليه الأغشام من العوام وجماعة من الأشرار، وهو أنه اسم لفعل من قوته تغيير الطبائع ونقل الصور، كجعل الإنسان حيوانا آخر وذكروا من ذلك خرافات توصلت بها الملحدة والبراهمة إلى إبطال النبوات والمعجزات، والثالث ما ذهب إليه محصلة أهل الأثر وعامة المتوسمين بالحكمة، وهو أنه عمل يقرب إلى الشيطان بمعونة منه، وذلك أن يوقع الساحر وهمه على أمر يريد فعله بالغير لافظا بكلمات من الشرك ومادحا للشيطان مستعينا به ... كذلك الشياطين لا تواصل ولا تعاون إلا الأشرار من الناس كل مشرك خبيث عابد للشيطان معاند للرحمن، ولهذا قال: ﴿هَلۡ أُنَبِّئُكُمۡ عَلَىٰ مَن تَنَزَّلُ ٱلشَّيَٰطِينُ ۝ تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٖ﴾", "en": "The verse says the devils taught people sorcery. Ar-Raghib sets out three views of what sorcery is.\n• Most dialectical theologians: mere trickery and illusion, with no reality — sleight of hand for the eyes and mumbling for the ears (\"they bewitched the eyes of the people\").\n• The ignorant among the common people: a power to change natures and turn one creature into another — tales that atheists and others then used to discredit prophets and miracles.\n• The people of the transmitted reports and those with wisdom — his view: an act that brings one near to Satan and is done with his help: the sorcerer fixes his mind on what he wants to do to someone, uttering words of shirk, praising Satan and seeking his aid.\nJust as the angels support only pure, devout people who resemble them in worship, the devils support only the wicked — \"shall I tell you on whom the devils descend? They descend on every sinful liar\".", "ar": "تقول الآية إن الشياطين علّموا الناس السحر. وذكر الراغب ثلاثة أقوالٍ في حقيقته:\n• أكثر الجدليّين: خداعٌ وتخييلاتٌ لا حقيقة لها — شعوذةٌ للأبصار وتمتمةٌ للأسماع: ﴿سَحَرُوٓاْ أَعۡيُنَ ٱلنَّاسِ﴾.\n• أغشام العوامّ: قوّةٌ تغيّر الطبائع وتنقل الصور كجعل الإنسان حيوانًا آخر — خرافاتٌ توصّل بها الملاحدة إلى إبطال النبوّات والمعجزات.\n• محصّلة أهل الأثر والمتوسّمون بالحكمة — وهو قوله: عملٌ يُتقرّب به إلى الشيطان بمعونةٍ منه: يُوقع الساحر وهمه على ما يريد فعله بالغير، لافظًا بكلمات الشرك، مادحًا للشيطان مستعينًا به.\nوكما أن الملائكة لا تواصل إلا أخيار الناس المتشبّهين بها في العبادة، فالشياطين لا تواصل إلا الأشرار: ﴿هَلۡ أُنَبِّئُكُمۡ عَلَىٰ مَن تَنَزَّلُ ٱلشَّيَٰطِينُ ۝ تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٖ﴾.", "links": [{"ref": "26:221-222", "q": "﴿هَلۡ أُنَبِّئُكُمۡ عَلَىٰ مَن تَنَزَّلُ ٱلشَّيَٰطِينُ ۝ تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٖ﴾", "en": "The devils come only to the wicked", "ar": "الشياطين لا تنزل إلا على الأشرار"}, {"ref": "43:36", "q": "﴿وَمَن يَعۡشُ عَن ذِكۡرِ ٱلرَّحۡمَٰنِ نُقَيِّضۡ لَهُۥ شَيۡطَٰنٗا فَهُوَ لَهُۥ قَرِينٞ﴾", "en": "Turning from Allah's remembrance invites a devil-companion", "ar": "الإعراض عن الذكر يجلب قرين الشيطان"}, {"ref": "7:116", "q": "﴿سَحَرُوٓاْ أَعۡيُنَ ٱلنَّاسِ وَٱسۡتَرۡهَبُوهُمۡ﴾", "en": "The trickery the first view points to", "ar": "الخداع الذي يشير إليه القول الأوّل"}], "v": 1, "p": 274, "pe": 274, "sid": 275},
  {"a": [102, 102], "h": "How a miracle differs from sorcery — and why sorcery is real", "hAr": "كيف تفترق المعجزة عن السحر — ولماذا للسحر حقيقة", "said": "قيل: الفرق بين ما يكون من فعل السحرة وبين ما يكون من الأنبياء لا يخفى على متنبه في المعرفة ومتدرج في أدنى منزلة من الحكمة، فإن تأثير السحر لا يكون إلا في فساد جزئي من كل مشرك خبيث في نفسه شرير في طبعه متدنس في بدنه ... ومتى قوبل بالاستعاذة بالله تعالى وبذكره بطل سلطانه، فأما ما كان من الأنبياء عليهم السلام، فلا يحصل إلا من كل مؤمن محصن الإيمان مقدس في نفسه خير في طبعه طاهر في بدنه [ويكون تأثيره] في أولي العقول الراجحة والأفهام البارعة، ويزداد بازدياد التقرب إلى الله تعالى ... ولو لم يكن للسحر حقيقة لما أعظم الله أمره في قوله: ﴿وَجَآءُو بِسِحۡرٍ عَظِيمٖ﴾، ولما أمروا بالتعوذ من شر النفاثات في العقد", "en": "If a person could, with Satan's help, learn hidden things and do what is beyond human habit, would that not blur the line between prophets and sorcerers — as unbelievers alleged of many prophets? Ar-Raghib says the difference is plain to anyone with the least wisdom. Sorcery only ever does some partial damage; it comes from someone foul in soul, evil in nature and unclean in body; it works mostly on weak minds and in filthy places; and when met with seeking refuge in Allah and remembering Him, its power is gone. What comes from the prophets comes from people pure in soul and body, works on the most intelligent and discerning, and grows stronger the nearer one draws to Allah.\nAnd sorcery does have a reality: otherwise Allah would not call the magicians' work \"a great sorcery\", nor command us to seek refuge \"from the evil of those who blow on knots\", nor would the law punish it so severely — mere gossip and trickery do not earn that.", "ar": "إن أمكن الإنسانَ بمعونة الشيطان أن يطّلع على غائبٍ ويفعل ما يخرج عن العادة، أفلا يلتبس طريق النبوّة بطريق السحر، كما زعم الزنادقة في كثيرٍ من الأنبياء؟ قال الراغب: الفرق لا يخفى على من له أدنى حكمة: فتأثير السحر لا يكون إلا في فسادٍ جزئيّ، ومن خبيث النفس شرّير الطبع متدنّس البدن، وأكثر ما يقع في ضعاف العقول والأمكنة القذرة، ومتى قوبل بالاستعاذة بالله وذكره بطل سلطانه. وما كان من الأنبياء فلا يكون إلا من مقدّس النفس طاهر البدن، ويؤثّر في أولي العقول الراجحة، ويزداد بازدياد التقرّب إلى الله.\nوللسحر حقيقة: فلولا ذلك ما عظّمه الله بقوله ﴿وَجَآءُو بِسِحۡرٍ عَظِيمٖ﴾، ولا أمر بالتعوّذ ﴿وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِي ٱلۡعُقَدِ﴾، ولا جاءت الشرائع بعقوبته الشديدة — والنميمة والخداع لا يُستحقّ بهما ذلك.", "links": [{"ref": "7:116", "q": "﴿وَجَآءُو بِسِحۡرٍ عَظِيمٖ﴾", "en": "Allah called it \"great\" — it is not nothing", "ar": "سمّاه الله «عظيمًا» — فليس لا شيء"}, {"ref": "113:4", "q": "﴿وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِي ٱلۡعُقَدِ﴾", "en": "We are told to seek refuge from it", "ar": "أُمرنا بالتعوّذ منه"}], "v": 1, "p": 275, "pe": 275, "sid": 276},
  {"a": [102, 102], "h": "The Prophet ﷺ was affected by sorcery — in his body, never in his prophethood", "hAr": "أصاب السحرُ النبيَّ ﷺ — في بدنه، لا في نبوّته", "said": "وقد أنكر الجدليون ما روي في ذلك من الأخبار الصحيحة والآثار الواضحة كنحو ما روي أن اليهود سحرت رسول الله - صلى الله عليه وسلم - ... قالوا: إن ذلك إن قلنا بصحته لكان يقدح في نبوته، وليس الأمر على ما ظنوه لما تقدم، ولأن تأثير السحر لم يكن في النبي - عليه السلام - من حيث ما هو نبي، وإنما كان في بدنه من حيث هو إنسان وبشر، وكما كان يأكل ويتغوط ويشرب ويمشي ويقعد ويغضب ويشتهي ويمرض ويصح من حيث هو بشر لا من حيث هو نبي ... كما أن جرحه وكسر ثنيته يوم أحد لم يقدح فيما ضمن الله له من عصمته، حيث قال: ﴿وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ﴾", "en": "The authentic reports tell that the Prophet ﷺ was bewitched by Labid ibn al-A'sam, and that two angels told him where the charm was hidden; when it was brought out and its knots undone, he felt as if freed from a tether. The dialectical theologians rejected these reports, saying that if true they would damage his prophethood.\nAr-Raghib answers: the sorcery did not touch him AS A PROPHET; it touched his body as a human being — just as he ate, drank, walked, grew angry, fell ill and recovered as a human, not as a prophet. It would damage prophethood only if it had touched something belonging to prophethood — his mind or his message — and it did not. His being protected from Satan does not mean nothing could ever affect his body, just as the wound and the broken tooth at Uhud did not break Allah's promise, \"Allah will protect you from the people.\"", "ar": "رُويت الأخبار الصحيحة أن لبيد بن الأعصم سحر النبي ﷺ، وأن ملَكين أخبراه بموضع السحر، فلمّا أُخرج وحُلّت عُقده وجد خفّةً كأنما نشط من عقال. فأنكر الجدليّون هذه الأخبار وقالوا: لو صحّت لقدحت في نبوّته.\nفأجاب الراغب: لم يؤثّر السحر فيه من حيث هو نبيّ، وإنما في بدنه من حيث هو إنسان، كما كان يأكل ويشرب ويمشي ويغضب ويمرض ويصحّ من حيث هو بشر. وإنما يقدح لو أثّر في شيءٍ يرجع إلى النبوّة — عقله أو رسالته — ولم يكن ذلك. وعصمته من الشيطان لا تقتضي ألّا يصيب بدنه شيء، كما أن جرحه وكسر ثنيّته يوم أحد لم يقدحا في قوله تعالى: ﴿وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ﴾.", "links": [{"ref": "5:67", "q": "﴿وَٱللَّهُ يَعۡصِمُكَ مِنَ ٱلنَّاسِۗ﴾", "en": "The promise of protection — kept, though he was wounded at Uhud", "ar": "وعد العصمة — محفوظٌ وإن جُرح يوم أحد"}], "v": 1, "p": 275, "pe": 276, "sid": 276},
  {"a": [102, 102], "h": "Harut and Marut: knowing evil in order to avoid it is not evil", "hAr": "هاروت وماروت: معرفة الشرّ لاجتنابه ليست شرًّا", "said": "والثالث قول أكثر المفسرين إن ﴿وَمَآ أُنزِلَ﴾ نصب معطوف على قوله السحر، ومعناه علم السحر وكيفية تعاطيه وقوله «منهما» راجع إلى الملكين، وكان تعليمهما ذلك ليحترز به، لا ليتعاطى فعلها ولهذا كانا يقولان ﴿إِنَّمَا نَحۡنُ فِتۡنَةٞ فَلَا تَكۡفُرۡۖ﴾ ... وذاك لما قد ثبت أن الحكمة معرفة الصدق من الكذب في الأقوال والخير من الشر في الأمور ليتحرى الصدق والخير ويتجنب الكذب والشر، فمعرفة الكذب والشر إذا واجبة كوجوب معرفة الصدق والخير، بل لا يتم معرفة أحدهما إلا بالآخر ... وإنما المستقبح تعاطي الكذب والقبيح، فإذا كان كذلك فلا ضير أن يبعث الله تعالى من قبله في وقت يكثر فيه الاستغواء بالسحر من ينبه على وجه احتياله، فتزول عن الناس الشبهة ... فما من شيء من المعادن أو من المعارف والعلوم نسخ في هذه الدار مصلح لخير إلا ويمكن استعماله في شر", "en": "Most interpreters read it this way: the two angels taught what sorcery is and how it is done — so that people could guard against it, not practise it — which is why they warned every learner, \"we are only a trial, so do not disbelieve.\"\nSome rejected this, thinking that knowing sorcery is forbidden like doing it. Ar-Raghib disagrees, and states a principle: wisdom is knowing truth from falsehood in speech and good from evil in deeds, in order to choose the truth and the good and avoid the rest. So knowing falsehood and evil is necessary, just as knowing truth and good is — indeed neither can be fully known without the other. What is ugly is DOING the lie and the evil. There is therefore no harm in Allah sending, at a time when people are being misled by sorcery, someone who exposes how its tricks work so the confusion lifts. And if a wicked person uses that knowledge for evil, it is like someone who learns law and worship to deceive people: there is nothing in this world, mineral or knowledge, fit for good that cannot also be used for evil.", "ar": "قال أكثر المفسّرين: علّم الملَكان حقيقة السحر وكيفيّته ليُحترز منه لا ليُتعاطى، ولهذا كانا يقولان لكلّ متعلّم: ﴿إِنَّمَا نَحۡنُ فِتۡنَةٞ فَلَا تَكۡفُرۡۖ﴾.\nوأنكر بعضهم ذلك ظنًّا منه أن علم السحر محظورٌ كفعله. فقال الراغب: ليس كذلك، وقرّر قاعدة: الحكمة معرفة الصدق من الكذب في الأقوال والخير من الشرّ في الأفعال، ليُتحرّى الصدق والخير ويُجتنب الكذب والشرّ؛ فمعرفة الكذب والشرّ واجبةٌ كوجوب معرفة الصدق والخير، بل لا تتمّ معرفة أحدهما إلا بالآخر، وإنما المستقبح تعاطي الكذب والقبيح. فلا ضير أن يبعث الله في وقتٍ كثر فيه الإغواء بالسحر من يكشف وجه حيلته فتزول الشبهة. ومن استعان بذلك على شرٍّ فهو كمن تعلّم الفقه والعبادات لإغواء الناس: «فما من شيءٍ من المعادن أو المعارف والعلوم مصلحٍ لخيرٍ إلا ويمكن استعماله في شرّ».", "links": [], "v": 1, "p": 278, "pe": 278, "sid": 279},
  {"a": [102, 102], "h": "\"Only by Allah's permission\" — everything happens by His decree, not everything by His command", "hAr": "﴿إِلَّا بِإِذۡنِ ٱللَّهِۚ﴾ — كلّ شيءٍ بقضائه، وليس كلّ شيءٍ بأمره", "said": "وينبغي أن يعلم أن الإذن في الشيء من الله تعالى ضربان، أحدهما: الإذن لقاصد الفعل في مباشرته نحو قولك: أذن الله لك أن تصل الرحم، والثاني: الإذن في تسخير الشيء على وجه تسخير السم في قتله من يتناوله والترياق في تخليصه من أذيته، فإذن الله تعالى في وقوع التسخير وتأثيره من القبيل الثاني، وذلك هو المشار إليه بالقضاء، وعلى هذا يقال: الأشياء كلها بإذن الله وقضائه، ولا يقال: الأشياء كلها بأمره ورضاه، والضر ما يعوق الإنسان عن فعل الخير سواء كان ذلك مما يعرض في بدنه، أو كان شيئا خارجا منه، والنفع ما يسهل سبيل الإنسان إلى الخير", "en": "\"They could harm no one by it except by Allah's permission.\" Does Allah \"permit\" sorcery? Ar-Raghib separates two kinds of permission. One is permission given to a person to do something — \"Allah permits you to keep ties with your relatives\". The other is permission in the sense of making a thing WORK — as poison is made to kill whoever swallows it, and an antidote to save him. The sorcery's effect is by the second kind of permission, which is what is meant by Allah's decree (qada'). So we say: all things happen by Allah's permission and decree; we do not say: all things happen by His command and with His pleasure.\nHe also defines harm and benefit: harm is whatever hinders a person from doing good, in his body or outside it; benefit is whatever eases his way to good. So \"what harms them and does not benefit them\": knowing sorcery could have benefited them had they used it to guard against deceivers; they used it against the truth, and it harmed them.", "ar": "﴿وَمَا هُم بِضَآرِّينَ بِهِۦ مِنۡ أَحَدٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ﴾: هل «يأذن» الله بالسحر؟ فرّق الراغب بين إذنين: إذنٍ لقاصد الفعل في مباشرته — «أذن الله لك أن تصل رحمك» —، وإذنٍ بمعنى تسخير الشيء ليؤثّر — كتسخير السمّ ليقتل من تناوله، والترياق ليخلّصه —. وتأثير السحر من الإذن الثاني، وهو المراد بالقضاء. ولهذا يقال: الأشياء كلّها بإذن الله وقضائه، ولا يقال: الأشياء كلّها بأمره ورضاه.\nوحدّ الضرّ والنفع: الضرّ ما يعوق الإنسان عن فعل الخير في بدنه أو خارجه، والنفع ما يُسهّل سبيله إلى الخير. فـ﴿وَيَتَعَلَّمُونَ مَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡۚ﴾: كان علم السحر ينفعهم لو احترزوا به من المُغوين، فاستعملوه في غير الحقّ فضرّهم.", "links": [], "v": 1, "p": 279, "pe": 279, "sid": 280},
  {"a": [102, 102], "h": "\"They knew\" … \"if only they knew\" — knowledge that is not acted on", "hAr": "﴿وَلَقَدۡ عَلِمُواْ﴾ … ﴿لَوۡ كَانُواْ يَعۡلَمُونَ﴾ — علمٌ لا يُعمل به", "said": "إن قيل: كيف أثبت لهم العلم في أول الكلام ونفى عنهم في آخره؟ فالجواب في ذلك من أوجه .. الأول: أن العلم المثبت لهم هو العقل الغريزي، وما جعله لهم بصيغته، والمنفي عنهم هو المكتسب الذي هو من جملة التكليف، والثاني: أن المثبت لهم هو العلم بالجملة، والمنفي عنهم هو العلم بالتفصيل، فقد يعلم الإنسان مثلا قبح الشيء ثم لا يعلم أن فعله قبيح ... والثالث: أنهم علموا عقاب الله، لكن لم يعلموا حقيقة عقابه وشدته، والرابع: أن معنى قوله ﴿لَوۡ كَانُواْ يَعۡلَمُونَ﴾ يعملون به، لأن من لا يعمل بما يعلم فهو في حكم من لا يعلم.", "en": "The same verse says \"they knew that whoever buys it has no share in the Hereafter\" and then \"evil is what they sold themselves for, if only they knew\". How can they know and not know? Four answers:\n• What they had was the knowledge built into their minds; what they lacked was the knowledge a person must acquire.\n• They knew in general, not in detail: a person can know a kind of act is ugly and not realise that what he is doing is of that kind.\n• They knew there is punishment, not how real and how severe it is.\n• \"If only they knew\" means \"if only they acted on it\" — for whoever does not act on what he knows is judged as one who does not know.", "ar": "قالت الآية ﴿وَلَقَدۡ عَلِمُواْ لَمَنِ ٱشۡتَرَىٰهُ مَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖۚ﴾، ثم ﴿لَوۡ كَانُواْ يَعۡلَمُونَ﴾. فكيف أثبت العلم ونفاه؟ أربعة أجوبة:\n• المثبَت العقل الغريزيّ، والمنفيّ العلم المكتسب الذي هو من جملة التكليف.\n• المثبَت العلم بالجملة، والمنفيّ العلم بالتفصيل: فقد يعلم الإنسان قبح الشيء ولا يعلم أن فعله هذا منه.\n• علموا أن ثَمّ عقابًا، ولم يعلموا حقيقته وشدّته.\n• ﴿لَوۡ كَانُواْ يَعۡلَمُونَ﴾ أي يعملون به، «لأن من لا يعمل بما يعلم فهو في حكم من لا يعلم».", "links": [], "v": 1, "p": 280, "pe": 281, "sid": 281},
  {"a": [103, 103], "h": "Reward (thawab): the good that comes back to you", "hAr": "الثواب: الخير الذي يعود إليك", "said": "الثؤوب: رجوع الشيء إلى حالة شبيهة بالحالة الأولى، يقال: ثاب الحوض إذا امتلأ بعد فراغه عقيب امتلائه ... والثواب والمثوبة في الخير تحصيل نفع يثوب إليه بإحسانه، ومعنى الآية: لو آمن الذين يتعلمون السحر واتقوا لأثيبوا وكان ذلك خيرا لهم", "en": "The root of thawab (reward) is a thing coming back to a state like its first — as a pool \"comes back\" full after it has been emptied. So reward is the benefit that comes back to a person because of the good he did. Had those who learned sorcery believed and been God-conscious, they would have been rewarded, and it would have been better for them — if only they knew.", "ar": "أصل «الثؤوب» رجوع الشيء إلى حالةٍ شبيهةٍ بالأولى، كما «يثوب» الحوض إذا امتلأ بعد فراغه. فالثواب نفعٌ يعود إلى الإنسان بإحسانه. ولو آمن الذين تعلّموا السحر واتّقوا لأُثيبوا، وكان ذلك خيرًا لهم لو كانوا يعلمون.", "links": [], "v": 1, "p": 281, "pe": 281, "sid": 282},
  {"a": [104, 104], "h": "\"Do not say ra'ina — say unzurna\": words that honour the Prophet ﷺ", "hAr": "﴿لَا تَقُولُواْ رَٰعِنَا وَقُولُواْ ٱنظُرۡنَا﴾: ألفاظٌ تليق بمقام النبي ﷺ", "said": "الرعي: حفظ الغير في أمر يعود بمصلحته، ومنه: رعي الغنم، ورعي الوالي الرعية ... وكان يقال للنبي - عليه السلام - [راعنا] أي استمع إلينا واحفظنا، فقالت اليهود: راعنا تعريضا به من الرعونة، فلما عوتبوا قالوا: إنما نقول مثل ما يقول المسلمون، فنهوا عن ذلك، وقيل لهم: قولوا بدل ذلك انظرنا، وذلك معناه معنى راعنا ... وقيل: إنما نهوا عن قولهم: «راعنا» لكونه مفاعلة متضمنة لمعنى المساواة بين المخاطب والمخاطب، فأمروا بتوقيره، كما قال ﴿لَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ بَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضٗاۚ﴾", "en": "Ra'y is looking after someone in what is good for him — as a shepherd tends his flock. The believers used to say to the Prophet ﷺ \"ra'ina\" — \"attend to us, look after us\". Some of the Jews said the same word meaning an insult from ru'unah, foolishness, and when rebuked said \"we only say what the Muslims say\". So the believers were told to use a word with the same meaning that could not be twisted: \"unzurna\", \"wait for us, look on us\".\nAnother view, from Ibn 'Abbas: \"ra'ina\" is a mutual form that suggests equality between the two speakers, so they were told to honour him — as elsewhere: \"do not make the calling of the Messenger among you like your calling of one another\".", "ar": "«الرعي» حفظ الغير فيما يعود بمصلحته، كرعي الغنم ورعي الوالي الرعيّة. وكان المسلمون يقولون للنبي ﷺ «راعِنا» أي استمع إلينا واحفظنا، فقالها بعض اليهود يريدون التعريض به من «الرعونة»، فلمّا عوتبوا قالوا: إنما نقول ما يقول المسلمون. فنُهي المؤمنون عنها، وأُمروا بلفظٍ معناه معناها لا يُحرَّف: «انظرنا».\nوقيل — عن ابن عباس —: «راعنا» مفاعلةٌ تتضمّن معنى المساواة بين المتخاطبَين، فأُمروا بتوقيره، كقوله: ﴿لَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ بَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضٗاۚ﴾.", "links": [{"ref": "4:46", "q": "﴿مِّنَ ٱلَّذِينَ هَادُواْ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ﴾", "en": "Twisting words — the habit this verse blocked", "ar": "تحريف الكلم — العادة التي سدّتها الآية"}, {"ref": "24:63", "q": "﴿لَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ بَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضٗاۚ﴾", "en": "Addressing him with honour", "ar": "خطابه بالتوقير"}, {"ref": "49:2", "q": "﴿وَلَا تَجۡهَرُواْ لَهُۥ بِٱلۡقَوۡلِ كَجَهۡرِ بَعۡضِكُمۡ لِبَعۡضٍ﴾", "en": "…and lowering the voice before him", "ar": "…وخفض الصوت عنده"}], "v": 1, "p": 281, "pe": 282, "sid": 282},
  {"a": [105, 105], "h": "\"Allah singles out for His mercy whom He wills\" — not because His grace is narrow", "hAr": "﴿وَٱللَّهُ يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۚ﴾ — لا لضيق فضله", "said": "وسبب نزول هذه الآية أن جماعة من اليهود كانوا يظهرون مودة المسلمين، ويزعمون أنهم يودون لهم الخير، فأكذبهم الله تعالى في ذلك ... ونهاهم تعريضا عن موادتهم ... وبين بآخر الآية أنه وإن اختص برحمته بعض الناس، فليس ذلك لضيق فضله، بل فضله عظيم، ورحمته [تسع كل شيء وإنما يسع رحمته] ضربان، أحدهما يصل إليه كل من شاء الوصول إليه من العباد بتمكين الله إياه وضرب يخص تعالى به بعض عباده", "en": "Some of them made a show of friendship to the Muslims and claimed to wish them well. Allah exposed them: \"those who disbelieve do not want any good to be sent down to you\" — and in doing so hinted to the believers not to take them as intimate friends.\nThe verse ends \"Allah singles out for His mercy whom He wills, and Allah is the Possessor of great grace\". Ar-Raghib: that He singles some out is not because His grace is narrow — His grace is vast and His mercy covers everything. His mercy is of two kinds: one that anyone who wishes can reach, because Allah has made it reachable for every servant; and one He gives specially to some of His servants.", "ar": "كان بعض اليهود يُظهرون مودّة المسلمين ويزعمون أنهم يريدون لهم الخير، فأكذبهم الله: ﴿مَّا يَوَدُّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَلَا ٱلۡمُشۡرِكِينَ أَن يُنَزَّلَ عَلَيۡكُم مِّنۡ خَيۡرٖ مِّن رَّبِّكُمۡۚ﴾، وفي ذلك نهيٌ للمؤمنين تعريضًا عن موادّتهم.\nوخُتمت بـ﴿وَٱللَّهُ يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ﴾: قال الراغب: ليس اختصاصه بعض الناس لضيق فضله، ففضله عظيمٌ ورحمته وسعت كلّ شيء. ورحمته ضربان: ضربٌ يصل إليه كلّ من شاء الوصول إليه من العباد بتمكين الله إياه، وضربٌ يخصّ به بعض عباده.", "links": [{"ref": "5:57", "q": "﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلَّذِينَ ٱتَّخَذُواْ دِينَكُمۡ هُزُوٗا وَلَعِبٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَٱلۡكُفَّارَ أَوۡلِيَآءَۚ﴾", "en": "The hint made plain in al-Ma'idah", "ar": "التعريض مصرّحًا به في المائدة"}], "v": 1, "p": 282, "pe": 283, "sid": 283},
  {"a": [106, 106], "h": "Why Allah changes a ruling — the two physicians of the soul", "hAr": "لماذا يغيّر الله الحكم — طبيبا النفس", "said": "إن لله تعالى خلفاء في الأرض مستخلفين فيها ومستعمرين فيها لنتوصل بذلك إلى مجاورته والقرب منه بحياة لا موت بعدها، وغنى لا حاجة معه، وقدرة لا يعتورها عجز، ولا سبيل إلى ذلك إلا باكتساب الصحة في النفس، وصحتها أمران: العلم والعمل ... كذلك لا سبيل إلى استفادة صحة النفس إلا بطبيبين أحدهما من داخل وهو العقل، والثاني من خارج وهو النبي وكما أن أدوية البدن وأغذيته العقاقير والأطعمة، فأدوية النفس الأعمال الشرعية والآداب الخلقية، وكما أن طبيب البدن قد يغير الأغذية والأدوية التي يتوصل بها إلى استفادة الصحة واستبقائها لاختلاف الأزمنة، كذلك الأنبياء من قبل الله قد يغير الأعمال الشرعية التي هي مصلحة للأنفس حسب ما يعرف الله من مصالحها، فكما يكون الشيء دواء للبدن في وقت، ثم يكون داء في وقت غيره، كذلك الأعمال قد تكون مصلحة في وقت، مفسدة في وقت", "en": "Some Jews, and a few Muslims, denied that Allah ever replaces a ruling, claiming that would mean He had changed His mind — something only one who does not know the outcome does. Ar-Raghib answers with one of his clearest pictures of what religion is for:\nAllah placed successors on earth to settle and build it, so that through that they reach nearness to Him — a life with no death after it, wealth with no need, power with no weakness. The only way there is the health of the soul, which is two things: knowledge (true from false, beautiful from ugly, good from evil) and action (choosing the true and the beautiful in word and deed). Just as the body's health needs two physicians — one inside, the power Allah placed in it to seek food, digest it and expel what harms, and one outside, the doctor who treats it when that power fails — the soul needs two: reason inside, and the prophet outside. The body's medicines and foods are drugs and meals; the soul's are the acts of the law and the manners of good character. And as a doctor changes foods and medicines as circumstances change — what was medicine at one time can be harmful at another — so Allah, through His prophets, changes acts of the law according to what He knows is good for souls.", "ar": "أنكر بعض اليهود وشرذمةٌ من المسلمين النسخ، زاعمين أنه «بَداء» لا يفعله إلا من يجهل العواقب. فأجاب الراغب بصورةٍ من أوضح ما قاله في غاية الدين:\nلله في الأرض خلفاء مستعمَرون فيها ليتوصّلوا بذلك إلى جواره والقرب منه: حياةٌ لا موت بعدها، وغنًى لا حاجة معه، وقدرةٌ لا يعتورها عجز. ولا سبيل إلى ذلك إلا بصحّة النفس، وصحّتها أمران: العلم — معرفة الصدق من الكذب والجميل من القبيح والخير من الشرّ — والعمل — تحرّي الصدق في المقال والجميل في الفعال. وكما لا تُستفاد صحّة البدن إلا بطبيبين: من داخل — القوّة التي سخّرها الله لاستدعاء الطعام وهضمه —، ومن خارج — الطبيب إذا اختلّت —، فكذلك النفس: طبيبها من داخل العقل، ومن خارج النبيّ. وأدوية البدن العقاقير والأطعمة، وأدوية النفس الأعمال الشرعية والآداب الخُلقية. وكما يغيّر الطبيب الأغذية والأدوية لاختلاف الأزمنة، فالشيء دواءٌ في وقتٍ وداءٌ في غيره، كذلك يغيّر الله على ألسنة أنبيائه الأعمال الشرعية بحسب ما يعلم من مصالح النفوس.", "links": [{"ref": "2:106", "q": "﴿مَا نَنسَخۡ مِنۡ ءَايَةٍ أَوۡ نُنسِهَا نَأۡتِ بِخَيۡرٖ مِّنۡهَآ أَوۡ مِثۡلِهَآۗ﴾", "en": "The verse that answers those who deny abrogation", "ar": "الآية التي تردّ على منكري النسخ"}, {"ref": "2:216", "q": "﴿وَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَهُوَ خَيۡرٞ لَّكُمۡۖ﴾", "en": "The heavier ruling can be the better one", "ar": "الحكم الأثقل قد يكون الأنفع"}], "v": 1, "p": 284, "pe": 285, "sid": 285},
  {"a": [106, 106], "h": "Allah moves everything from state to state — and why Islam is the final law", "hAr": "الله ينقل كلّ شيءٍ من حالٍ إلى حال — ولماذا كان الإسلام الشريعة الخاتمة", "said": "ومما يبين جواز النقل من حكم إلى حكم نقل الله تعالى الأشياء [من] حال إلى حال حتى ينتهي إلى أقصى الكمال ... وذلك من حين النطفة، ثم العلق، ثم المضغة، ثم كونه جنينا، ثم طفلا، ثم ناشئا وكهلا وشيخا وهرما ... ولو كان نقل الشرع من حال إلى حال قبيحا لكان بعثة موسى ونقله اليهود عن بعض ما كانوا عليه قبيحا ... إنا لم نعلم كون دينه - عليه السلام - على التأبيد من قوله فقط، بل علمنا ذلك ... ببرهان، وهو أن دينه بالاعتبار العقلي وسط كما وصفه تعالى بقوله: ﴿جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا﴾ وأنه مصون عن الإفراط والتفريط والوسط الذي هذه صفته هو الحق الذي قال تعالى فيه: ﴿فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَٰلُۖ﴾", "en": "Moving from one ruling to another is how Allah treats everything He makes: He carries each thing from state to state until it reaches its fullest completion — as He carries a human from a drop to a clot, to a lump, to a foetus, a child, a youth, a man, an old man. And if moving a law from one state to another were ugly, then Musa's own mission — which moved the Children of Israel from some of what they had been doing — would be ugly too.\nBut then how do we know Islam will not be replaced? Ar-Raghib: not only from the Prophet's words, but by proof. His religion is, by the test of reason, the middle way — \"We made you a middle nation\" — guarded from excess and from falling short. And the middle that has this quality is the truth itself, \"and what is there after the truth but error?\"", "ar": "النقل من حكمٍ إلى حكم هو سنّة الله في كلّ ما خلق: ينقل الأشياء من حالٍ إلى حالٍ حتى تبلغ أقصى كمالها، كنقل الإنسان من النطفة إلى العلقة إلى المضغة إلى الجنين إلى الطفل إلى الناشئ والكهل والشيخ. ولو كان نقل الشرع من حالٍ إلى حالٍ قبيحًا لكانت بعثة موسى — التي نقلت بني إسرائيل عن بعض ما كانوا عليه — قبيحة.\nفكيف نعلم أن الإسلام لا يُنسخ؟ قال الراغب: لا من قوله ﷺ وحده، بل ببرهان: فدينه بالاعتبار العقليّ وسط — ﴿جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا﴾ — مصونٌ عن الإفراط والتفريط، والوسط الذي هذه صفته هو الحقّ، ﴿فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَٰلُۖ﴾.", "links": [{"ref": "2:143", "q": "﴿وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا﴾", "en": "The middle way — the proof that this law is final", "ar": "الوسط — برهان أن هذه الشريعة خاتمة"}, {"ref": "10:32", "q": "﴿فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَٰلُۖ﴾", "en": "After the truth, only error", "ar": "ليس بعد الحقّ إلا الضلال"}, {"ref": "2:106", "q": "﴿أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ﴾", "en": "Changing a ruling is not weakness", "ar": "تغيير الحكم ليس عجزًا"}], "v": 1, "p": 285, "pe": 286, "sid": 286},
  {"a": [106, 106], "h": "\"Better than it, or like it\" — and why the new ruling need not be the easier one", "hAr": "﴿بِخَيۡرٖ مِّنۡهَآ أَوۡ مِثۡلِهَآۗ﴾ — ولماذا لا يلزم أن يكون الناسخ أخفّ", "said": "وتعلق أهل الظاهر بالآية، حيث ذكروا أن الناسخ لا بد أن يكون أخف من المنسوخ، وذهبوا في الخفة إلى ما يستخفه النفس بالطبع، وذلك بعيد، فإن الشريعة مبنية على مخالفة النفس وعلى مجانبة مقتضى الطبع، ولهذا قيل: إذا عن أمران، فاشتبه وجه الصواب فتخير أثقلهما على النفس، وعلى هذا قوله تعالى: ﴿وَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَهُوَ خَيۡرٞ لَّكُمۡۖ﴾ ... فإن التخفيف واليسر في الأمور الإلهية في الدنيا والآخرة هما مما تستثقله النفس، أما في الآخرة، فإنه لا وصول إلى ذلك إلا بتحمل المشاق في الدنيا والعمل بالطاعات ومخالفة الهوى", "en": "\"Like it\": a ruling kept but given new words can be called \"the same\" if you look at the ruling itself, or \"like it\" if you look at its clothing, the words — as the water in a well is the same water as the river's in kind, yet \"like\" it if you look at where it sits.\nThe literalists took \"better than it\" to mean the new ruling must always be LIGHTER, in the sense of easier on the self. Ar-Raghib calls that far-fetched: the law is built on going against the self and against what nature craves — hence the saying, \"when two courses face you and you cannot tell which is right, choose the one heavier on the self\", and \"perhaps you hate a thing and it is good for you\". Even the \"ease\" Allah wants for us is heavy to the self: the ease of the Hereafter is reached only by bearing hardships here — obedience and going against one's desires.", "ar": "﴿أَوۡ مِثۡلِهَآۗ﴾: الحكم الذي بقي وأُنزل في لفظٍ جديد يصحّ أن يُقال «هو هو» باعتبار نفسه، و«مثله» باعتبار كسوته التي هي اللفظ، كما يُقال ماء البئر هو ماء النهر باعتبار الجنس، ومثله باعتبار القرار.\nوتعلّق أهل الظاهر بـ﴿بِخَيۡرٖ مِّنۡهَآ﴾ فقالوا: لا بدّ أن يكون الناسخ أخفّ، أي أيسر على النفس بالطبع. فقال الراغب: هذا بعيد، فالشريعة مبنيّةٌ على مخالفة النفس ومجانبة مقتضى الطبع؛ ولهذا قيل: «إذا عنّ أمران فاشتبه وجه الصواب فتخيّر أثقلهما على النفس»، و﴿وَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَهُوَ خَيۡرٞ لَّكُمۡۖ﴾. بل التخفيف واليسر في الأمور الإلهيّة ممّا تستثقله النفس: فيسر الآخرة لا يُوصل إليه إلا بتحمّل المشاقّ في الدنيا والطاعة ومخالفة الهوى.", "links": [], "v": 1, "p": 287, "pe": 288, "sid": 288},
  {"a": [107, 107], "h": "No protector, no helper besides Him — and why the two words", "hAr": "﴿مِن وَلِيّٖ وَلَا نَصِيرٍ﴾ — ولماذا اللفظان", "said": "وإنما ذكر الولي والنصير، وهما متقاربان بالمعنى، لأنه قد ينفك الولي من النصرة بأن يكون ضعيفا، والنصير من الولاية بأن يكون عن المنصور أجنبيا، وقوله: ﴿وَمَا لَكُم مِّن دُونِ ٱللَّهِ﴾ إذا تصور خطابا للكفار اقتضى وعيدا ... وإذا تصور خطابا للمؤمنين اقتضى تسكينا لهم أي لا تعتدوا بمن يواليكم وينصركم سواه ... والقصد بالآية، أنهم لما أنكروا النسخ عرفهم أنه تعالى ينقل عباده من حكم إلى حكم على ما يرى من مصالحهم، وبين أن ذلك ليس لعجزه، إذ هو قادر على كل شيء ومالك له", "en": "Why both \"protector\" and \"helper\"? Because one can be without the other: a friend and ally may be too weak to help, and a helper may be a stranger with no bond to you. \"You have neither besides Allah\": to the disbelievers it is a threat — no one will shield you from Him; to the believers it is comfort — count on no one's friendship and help but His.\nAnd the thread of the passage: they denied that rulings change, so Allah reminds them that He moves His servants from ruling to ruling for their good, and that it is not from weakness — He is able to do all things, and the kingdom of the heavens and the earth is His. The second \"do you not know\" gives the reason for the first: He is able to do everything BECAUSE everything is His.", "ar": "لماذا ذكر الوليّ والنصير وهما متقاربان؟ لأن أحدهما قد ينفكّ عن الآخر: فالوليّ قد يكون ضعيفًا لا ينصر، والنصير قد يكون أجنبيًّا عن المنصور. و﴿وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٍ﴾: إن كان للكفار فهو وعيد — لا وليّ ولا ناصر يحميكم منه —، وإن كان للمؤمنين فهو تسكين — لا تعتدّوا بوليٍّ ولا نصيرٍ سواه.\nوسياق الآيات: أنكروا النسخ، فعرّفهم أنه ينقل عباده من حكمٍ إلى حكمٍ بحسب مصالحهم، وأن ذلك ليس لعجز، فهو على كلّ شيءٍ قدير، وله ملك السماوات والأرض. و﴿أَلَمۡ تَعۡلَمۡ﴾ الثانية علّةٌ للأولى: قادرٌ على كلّ شيء لأن له ملك كلّ شيء.", "links": [{"ref": "17:67", "q": "﴿ضَلَّ مَن تَدۡعُونَ إِلَّآ إِيَّاهُۖ﴾", "en": "Every other helper disappears when needed", "ar": "يضلّ كلّ مدعوٍّ سواه"}], "v": 1, "p": 288, "pe": 289, "sid": 289},
  {"a": [108, 108], "h": "\"Straying from the level road\" — the first step of losing faith", "hAr": "﴿فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ﴾ — أوّل خطوةٍ إلى فقد الإيمان", "said": "إن قيل: ما فائدة قوله: ﴿وَمَن يَتَبَدَّلِ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ﴾ ... وفي ذلك تنبيه أن ضلالة سواء السبيل قائدة إلى الكفر بعد الإيمان، ومعناه: «لا تسألوا رسولكم كما سئل موسى فتضلوا سواء السبيل فيؤدي بكم إلى تبديل الكفر بالإيمان»، فمبدأ ذلك الضلال عن سواء السبيل ... ووجه رابع: وهو أن سواء السبيل إشارة إلى الفطرة التي فطر الناس عليها، والإيمان إشارة إلى المكتسب من جهة الشرائع، فقال: ﴿وَمَن يَتَبَدَّلِ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ﴾ أي بالإيمان المكتسب فقد أبطله وضيع الفطرة التي فطر الناس عليها، فلا يرجى له نزوع عما هو عليه بعد ذلك", "en": "\"Do you want to question your Messenger as Musa was questioned before?\" — like demanding a book sent down from the sky, or, as some Companions once asked, a tree to hang their weapons on like the idolaters', to which the Prophet ﷺ said: \"Allahu akbar — you have asked as the Children of Israel asked Musa, 'make us a god like their gods'.\"\n\"Whoever exchanges faith for disbelief has strayed from the level road\": is that not obvious? Ar-Raghib gives several readings. The order is a warning of the sequence: straying from the level road is what leads to disbelief after faith — so do not start down it with such demands. Or: stubbornness after proofs that satisfy the heart is called disbelief because it leads there, as grape juice is called \"wine\". Or: the \"level road\" is the natural disposition people are created with, and \"faith\" is what they gain from revelation; whoever exchanges that faith for disbelief has thrown away both — and then there is little hope of his turning back.\n\"Sawa'\" means the middle, the direct way, and justice: these are one meaning, not different opinions as some commentators thought.", "ar": "﴿أَمۡ تُرِيدُونَ أَن تَسۡـَٔلُواْ رَسُولَكُمۡ كَمَا سُئِلَ مُوسَىٰ مِن قَبۡلُۗ﴾ — كطلب كتابٍ ينزل من السماء، أو كما سأل بعضهم «ذات أنواط» شجرةً يعلّقون عليها أسلحتهم كالمشركين، فقال ﷺ: «الله أكبر، سألتم كما سأل بنو إسرائيل موسى: اجعل لنا إلهًا كما لهم آلهة».\nو﴿وَمَن يَتَبَدَّلِ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ﴾: أليس هذا ظاهرًا؟ ذكر الراغب أوجهًا: أنه تنبيهٌ على الترتيب: الضلال عن سواء السبيل يقود إلى الكفر بعد الإيمان، فلا تبدؤوا به بمثل هذه المطالب؛ أو أن معاندة الأنبياء بعد ما تسكن إليه النفس سُمّيت كفرًا لأنها تؤدّي إليه، كتسمية العصير خمرًا؛ أو أن «سواء السبيل» الفطرة التي فطر الناس عليها، و«الإيمان» المكتسب من الشرائع، فمن بدّل الكفر بالإيمان أبطله وضيّع الفطرة معًا، فلا يُرجى له نزوعٌ بعد ذلك.\nو«السواء»: الوسط والقصد والعدل، وهي معنًى واحد لا أقوالٌ مختلفة كما ظنّ بعض المفسّرين.", "links": [{"ref": "4:153", "q": "﴿يَسۡـَٔلُكَ أَهۡلُ ٱلۡكِتَٰبِ أَن تُنَزِّلَ عَلَيۡهِمۡ كِتَٰبٗا مِّنَ ٱلسَّمَآءِۚ﴾", "en": "The kind of demand this warns against", "ar": "نوع الطلب الذي تحذّر منه الآية"}, {"ref": "30:30", "q": "﴿فَأَقِمۡ وَجۡهَكَ لِلدِّينِ حَنِيفٗاۚ فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ﴾", "en": "The \"level road\" as the natural disposition", "ar": "«سواء السبيل» بمعنى الفطرة"}], "v": 1, "p": 290, "pe": 290, "sid": 291},
  {"a": [109, 109], "h": "Envy: stinginess with a gift that is not even yours — and pardon versus overlooking", "hAr": "الحسد: بخلٌ بنعمةٍ ليست لك — والعفو غير الصفح", "said": "الحسد: كراهية نعمة على مستحق لها، وعدت من عظائم الذنوب، إذ هو معاندة الله في إرادته، وهو شر من البخل، فإن الحسد بخل على الغير بنعمة من لا تنفد العطايا نعمه، والعفو ترك العقوبة على المذنب، والصفح ترك تثريبه، وقد يعفو الإنسان ولا يصفح ... وقوله: ﴿مِّنۡ عِندِ أَنفُسِهِم﴾ أي من عند هواهم كقوله تعالى: ﴿وَٱتَّبَعُوٓاْ أَهۡوَآءَهُم﴾، وعبر عن الهوى بالنفس وهي الأمارة بالسوء، وبين أنهم فعلوا ذلك بعد وضوح الحق لهم، ولكنهم بحسدهم وهواهم لا يتحرونه، ولا يحبون أن يتحراه غيرهم", "en": "Envy is resenting a blessing on someone who deserves it. It counts among the gravest sins because it sets a person against Allah's will — and it is worse than miserliness: the envious is being miserly with a gift that belongs to the One whose giving never runs out.\n\"Out of envy from within themselves\" — from their own desire, the self that commands evil. They saw the truth clearly, but their envy and desire made them unwilling to follow it — and unwilling to let others follow it.\n\"So pardon and overlook\": pardon ('afw) is letting go of the punishment; overlooking (safh) is letting go of the blame — turning the page on the offence. A person can pardon and still reproach; the command asks for both.", "ar": "«الحسد» كراهية نعمةٍ على مستحقّها، وعُدّ من عظائم الذنوب لأنه معاندةٌ لله في إرادته، وهو شرٌّ من البخل: فالحاسد يبخل على غيره بنعمة من لا تنفد عطاياه.\nو﴿مِّنۡ عِندِ أَنفُسِهِم﴾: من عند هواهم، والنفس هي الأمّارة بالسوء. فعلوا ذلك بعد أن تبيّن لهم الحقّ، لكنهم بحسدهم وهواهم لا يتّبعونه ولا يحبّون أن يتّبعه غيرهم.\nو﴿فَٱعۡفُواْ وَٱصۡفَحُواْ﴾: العفو ترك العقوبة، والصفح ترك التثريب — طيّ صفحة الذنب. وقد يعفو الإنسان ولا يصفح، والأمر بهما معًا.", "links": [{"ref": "47:14", "q": "﴿وَٱتَّبَعُوٓاْ أَهۡوَآءَهُم﴾", "en": "\"From within themselves\" — from desire", "ar": "«من عند أنفسهم» — من الهوى"}], "v": 1, "p": 291, "pe": 291, "sid": 292},
  {"a": [110, 110], "h": "\"Whatever good you send ahead, you will find it with Allah\"", "hAr": "﴿وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِۗ﴾", "said": "هذا معطوف على قوله: ﴿فَٱعۡفُواْ وَٱصۡفَحُواْ﴾، ومعناه: اشتغلوا بالعبادات التي يعود عليكم فعلها نحو: ﴿وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ﴾، وجعل ثواب الفعل نفس الفعل لكونه إياه في التقدير ... وبين أن كل خير حصله الإنسان فمدخر له بخلاف عمل الكفار الذي قال فيه: ﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾، وبخلاف عمل الدنيا الذي قال فيه: ﴿كَسَرَابِۭ بِقِيعَةٖ﴾، وعلى ذلك قال: ﴿يَوۡمَ تَجِدُ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ مِنۡ خَيۡرٖ مُّحۡضَرٗا وَمَا عَمِلَتۡ مِن سُوٓءٖ﴾", "en": "This follows \"pardon and overlook\": instead of being consumed by their hostility, busy yourselves with the worship whose benefit returns to you — as in \"seek help in patience and prayer\". \"You will find IT\": the reward is called by the deed's own name, because it is the deed returned to you.\nEvery good a person does is stored up for him — unlike the deeds of the disbelievers, which \"We will turn into scattered dust\", and unlike work for this world alone, which is \"like a mirage in a plain\". \"On the Day every soul will find what good it did brought forward.\" And if someone's good deeds were nullified, how does he \"find\" them? Because the good truly sent ahead is the good that was not nullified; what was nullified has ceased to be good, though a weak eye may still call it so.", "ar": "هذا معطوفٌ على ﴿فَٱعۡفُواْ وَٱصۡفَحُواْ﴾: بدل الانشغال بعداوتهم، اشتغلوا بالعبادات التي يعود عليكم نفعها، كقوله ﴿وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ﴾. و﴿تَجِدُوهُ﴾: جعل ثواب الفعل نفسَ الفعل، لأنه هو عائدًا إليكم.\nوكلّ خيرٍ حصّله الإنسان مدّخرٌ له، بخلاف عمل الكفار الذي ﴿فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾، وبخلاف عمل الدنيا وحدها الذي ﴿كَسَرَابِۭ بِقِيعَةٖ﴾: ﴿يَوۡمَ تَجِدُ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ مِنۡ خَيۡرٖ مُّحۡضَرٗا﴾. وكيف يجد من حبط عمله؟ الخير المقدَّم حقيقةً هو الذي لم يحبط، وما حبط فقد خرج عن كونه خيرًا، وإن سمّاه خيرًا من ضعف نظره.", "links": [{"ref": "3:30", "q": "﴿يَوۡمَ تَجِدُ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ مِنۡ خَيۡرٖ مُّحۡضَرٗا﴾", "en": "Every good deed found again", "ar": "كلّ خيرٍ يوجَد يومئذٍ"}, {"ref": "25:23", "q": "﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾", "en": "Deeds that turn to dust", "ar": "أعمالٌ تصير هباءً"}, {"ref": "99:7", "q": "﴿فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ﴾", "en": "Not an atom is lost", "ar": "لا تضيع ذرّة"}], "v": 1, "p": 292, "pe": 292, "sid": 293},
  {"a": [111, 111], "h": "\"Bring your proof, if you are truthful\" — claims need proof, not wishes", "hAr": "﴿قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ﴾ — الدعوى تحتاج برهانًا لا أمنيّة", "said": "البرهان: كل حجة لا يعتريها شبهة بوجه ... وقوله: ﴿لَن يَدۡخُلَ﴾ كلام \" ملفوف \" وتقديره: قالت اليهود لن يدخل الجنة إلا من كان هودا، وقالت النصارى: لن يدخلها إلا النصارى فأجمل اكتفاء بعلم السامع أن يرد كلا إلى ما يقتضيه ونحوه في الإجمال قوله- عز وجل- ﴿جَعَلَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ لِتَسۡكُنُواْ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ﴾. ثم [كذبهم] بعجزهم عن إقامة البرهان على ما ادعوه.", "en": "A burhan, \"proof\", is an argument that no doubt can touch in any way.\n\"None will enter Paradise except a Jew or a Christian\" is a folded sentence: the Jews said \"none but Jews will enter it\", the Christians said \"none but Christians\". The verse gathers the two claims into one and trusts the listener to hand each back to its owner — just as \"He made for you the night and the day, that you may rest in it and seek of His bounty\": the rest belongs to the night, the seeking to the day. Then Allah exposed the claim simply by their inability to bring any proof for it.\n\"Hud\" (Jews): al-Farra' said it is \"yahud\" with its extra ya dropped; others said it is the plural of ha'id, \"one who turns back in repentance\", as Musa said \"we have turned back to You\" — so it began as a name of praise for those who repented, and after their law was superseded it stayed on their community as a mere name.", "ar": "«البرهان» كلّ حجّةٍ لا يعتريها شبهةٌ بوجه.\nو﴿لَن يَدۡخُلَ ٱلۡجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوۡ نَصَٰرَىٰۗ﴾ كلامٌ «ملفوف»: قالت اليهود لن يدخلها إلا من كان هودًا، وقالت النصارى لن يدخلها إلا النصارى، فجمع القولين اكتفاءً بعلم السامع أن يردّ كلًّا إلى صاحبه، كقوله: ﴿جَعَلَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ لِتَسۡكُنُواْ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ﴾ — السكون لليل والابتغاء للنهار. ثم أبطل دعواهم بعجزهم عن إقامة البرهان عليها.\nو«هود»: قال الفرّاء: أصله «يهود» فحُذفت ياؤه الزائدة؛ وقال غيره: جمع «هائد» أي تائب، من قول موسى ﴿إِنَّا هُدۡنَآ إِلَيۡكَۚ﴾، فكان في الأصل اسم مدحٍ لمن تاب، ثم صار بعد نسخ شريعتهم لازمًا لجماعتهم كالعَلَم.", "links": [{"ref": "7:156", "q": "﴿إِنَّا هُدۡنَآ إِلَيۡكَۚ﴾", "en": "\"Hud\" — from Musa's \"we have turned back to You\"", "ar": "«هود» من قول موسى: هُدنا إليك"}, {"ref": "28:73", "q": "﴿جَعَلَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ لِتَسۡكُنُواْ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ﴾", "en": "The same folded style: each part returns to its owner", "ar": "الأسلوب الملفوف نفسه: يُردّ كلٌّ إلى صاحبه"}, {"ref": "2:94", "q": "﴿قُلۡ إِن كَانَتۡ لَكُمُ ٱلدَّارُ ٱلۡأٓخِرَةُ عِندَ ٱللَّهِ خَالِصَةٗ مِّن دُونِ ٱلنَّاسِ﴾", "en": "The same claim of owning Paradise, answered before", "ar": "الدعوى نفسها بامتلاك الجنة، وقد رُدّت قبلُ"}], "v": 1, "p": 293, "pe": 293, "sid": 294},
  {"a": [112, 112], "h": "Islam has a beginning and a summit — and Ibrahim is the summit", "hAr": "للإسلام مبدأٌ ومنتهى — وإبراهيم منتهاه", "said": "بل: رد لدعواهم وإثبات لضد حكمهم، والإسلام: الدخول في السلم ... وجعل الإسلام في الشرع ضربين، ضربا قبل الإيمان دونه، وهو الاعتراف باللسان الذي يحقن الدماء حصل معه الاعتقاد الصحيح أو لم يحصل، وإياه عنى بقوله - عز وجل -: ﴿قَالَتِ ٱلۡأَعۡرَابُ ءَامَنَّاۖ قُل لَّمۡ تُؤۡمِنُواْ وَلَٰكِن قُولُوٓاْ أَسۡلَمۡنَا﴾ وضربا بعد الإيمان وفوقه، وهو أن يكون مع الاعتراف اعتقاد بالقلب ووفاء بالفعل، وإياه عنى يوسف بقوله: ﴿تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ﴾ ... وهذا الإسلام بين مبدأه ومنتهاه بون بعيد، وكان منتهاه على حسب طاقة البشر حال إبراهيم- عليه السلام- حيث ابتلى، فقيل له أسلم، فقال أسلمت لرب العالمين، ثم وفي بما كان منه، وهذا هو الإخلاص المراد من الأولياء", "en": "\"Nay (bala)\" rejects their claim and affirms its opposite. Islam is \"entering into peace (silm)\"; yielding is called islam because yielding to the one at peace with you is what peace requires.\nIn the law, ar-Raghib says, Islam is of two kinds. One comes before faith and below it: the declaration of the tongue, which protects a person's life whether or not true belief is with it — the Bedouins who were told \"you have not believed; say rather 'we have submitted'\". The other comes after faith and above it: the declaration together with belief in the heart and fulfilment in deeds — what Yusuf asked for: \"take my soul as a Muslim and join me with the righteous\".\nBetween the start of this Islam and its end there is a vast distance. Its summit, as far as human capacity goes, was the state of Ibrahim when he was tested: he was told \"submit\", he said \"I submit to the Lord of the worlds\" — and then he lived up to what he had said. That is the sincerity asked of the friends of Allah.", "ar": "﴿بَلَىٰۚ﴾ ردٌّ لدعواهم وإثباتٌ لضدّ حكمهم. و«الإسلام» الدخول في السِّلم، وسُمّي الانقياد إسلامًا لأن الانقياد للمسالم من مقتضى السلم.\nوهو في الشرع — عند الراغب — ضربان: ضربٌ قبل الإيمان ودونه: الاعتراف باللسان الذي يحقن الدماء، حصل معه الاعتقاد الصحيح أو لم يحصل، وإياه عنى بقوله: ﴿قَالَتِ ٱلۡأَعۡرَابُ ءَامَنَّاۖ قُل لَّمۡ تُؤۡمِنُواْ وَلَٰكِن قُولُوٓاْ أَسۡلَمۡنَا﴾؛ وضربٌ بعد الإيمان وفوقه: أن يكون مع الاعتراف اعتقادٌ بالقلب ووفاءٌ بالفعل، وإياه عنى يوسف: ﴿تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ﴾.\nوبين مبدأ هذا الإسلام ومنتهاه بونٌ بعيد، ومنتهاه — على قدر طاقة البشر — حال إبراهيم حين ابتُلي: ﴿إِذۡ قَالَ لَهُۥ رَبُّهُۥٓ أَسۡلِمۡۖ قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ﴾، ثم وفّى بما قال. وهذا هو الإخلاص المراد من الأولياء.", "links": [{"ref": "49:14", "q": "﴿قَالَتِ ٱلۡأَعۡرَابُ ءَامَنَّاۖ قُل لَّمۡ تُؤۡمِنُواْ وَلَٰكِن قُولُوٓاْ أَسۡلَمۡنَا﴾", "en": "The first kind: Islam of the tongue", "ar": "الضرب الأول: إسلام اللسان"}, {"ref": "12:101", "q": "﴿تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ﴾", "en": "The higher kind: Yusuf's prayer", "ar": "الضرب الأعلى: دعاء يوسف"}, {"ref": "2:131", "q": "﴿إِذۡ قَالَ لَهُۥ رَبُّهُۥٓ أَسۡلِمۡۖ قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ﴾", "en": "The summit: Ibrahim", "ar": "المنتهى: إبراهيم"}, {"ref": "53:37", "q": "﴿وَإِبۡرَٰهِيمَ ٱلَّذِي وَفَّىٰٓ﴾", "en": "\"…and then he lived up to it\"", "ar": "«ثم وفّى بما كان منه»"}], "v": 1, "p": 293, "pe": 294, "sid": 294},
  {"a": [112, 112], "h": "\"Submits his face… while doing good\" — and the fear that is lifted", "hAr": "﴿أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ﴾ — والخوف الذي يُرفع", "said": "وأصل الوجه العضو المقابل من الإنسان فاستعير للمقابل من كل شيء حتى قيل: واجهته ووجهته، وقيل للقصد وجه، وللمقصد وجهة، وعلى ذلك ﴿أَسۡلَمَ وَجۡهَهُۥ﴾، ﴿وَمَن يُسۡلِمۡ وَجۡهَهُۥٓ إِلَى ٱللَّهِ﴾، ﴿أَسۡلَمۡتُ وَجۡهِيَ لِلَّهِ﴾ ... والإحسان قيل هو الإتيان بعد فرض العبادة بالنفل، وبعد إقامة العدل بالفضل ... ومع ذلك فلا خوف عليه في الدنيا ولا في الآخرة، أما في الدنيا فبأن يجعل له يقينا وصبرا وقناعة تكفيه الخوف على شيء يفوته والجزع لشيء قد فاته ... إن قيل: كيف قال ﴿لَا خَوۡفٌ عَلَيۡهِمۡ﴾ وقد مدح المؤمنين على خوفهم بقوله: ﴿وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ﴾ قيل: إن الذي نفي عنهم هو ما تقدم آنفا، والذي مدحهم به هو توفية حق العبادة، فإن مخافة الله إقامة عباداته وارتسام مرسوماته", "en": "The face is the part of a person that faces; the word was borrowed for the facing side of anything, and then for one's aim: to \"submit one's face to Allah\" is to make Him the aim of everything one seeks — or, as others say, \"face\" here stands for the whole self: he handed himself over, as in \"Allah has bought from the believers their selves and their wealth\".\nIhsan, \"doing good\", was explained as following the obligatory worship with the voluntary, and following justice with generosity.\nSuch a person gets what they claimed and more: his reward, Paradise; and no fear upon him in this world or the next. In this world, Allah gives him certainty, patience and contentment that spare him fear for what he might lose and grief for what he has already lost; in the next, He spares him its terrors.\nBut are believers not praised for fearing — \"they hope for His mercy and fear His punishment\"? Ar-Raghib: the fear lifted from them is that anxiety; the fear they are praised for is fulfilling the right of worship — fearing Allah means establishing His worship and following what He has laid down.", "ar": "أصل «الوجه» العضو المقابل من الإنسان، فاستُعير للمقابل من كلّ شيء، ثم قيل للقصد «وجه» وللمقصد «وجهة»؛ فـ﴿أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ﴾: جعله مقصده في كلّ ما يتحرّاه — أو «الوجه» هنا النفس: أسلم نفسه له، كقوله: ﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم﴾.\nو«الإحسان» قيل: الإتيان بعد فرض العبادة بالنفل، وبعد إقامة العدل بالفضل.\nفمن كان كذلك حصل له ما ادّعوه وزيادة: أجره الجنة، ولا خوف عليه في الدنيا ولا في الآخرة: أمّا في الدنيا فيجعل الله له يقينًا وصبرًا وقناعةً تكفيه الخوف على ما يفوته والجزع على ما فاته، وأمّا في الآخرة فيكفيه شدائدها.\nفإن قيل: أليس المؤمنون ممدوحين بالخوف: ﴿وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ﴾؟ قيل: المنفيّ عنهم ذلك القلق، والممدوح توفية حقّ العبادة؛ فمخافة الله إقامة عباداته وارتسام مرسوماته.", "links": [{"ref": "31:22", "q": "﴿وَمَن يُسۡلِمۡ وَجۡهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنٞ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ﴾", "en": "The same two conditions: face submitted, doing good", "ar": "الشرطان نفساهما: إسلام الوجه والإحسان"}, {"ref": "9:111", "q": "﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم﴾", "en": "\"His face\" = himself, handed over", "ar": "«وجهه» أي نفسه، أسلمها لله"}, {"ref": "17:57", "q": "﴿وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ﴾", "en": "The fear that is praised", "ar": "الخوف الممدوح"}], "v": 1, "p": 294, "pe": 295, "sid": 295},
  {"a": [113, 113], "h": "\"The Jews say the Christians stand on nothing…\" — why blanket verdicts are condemned", "hAr": "﴿لَيۡسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَيۡءٖ﴾ — لماذا ذُمّ الحكم المطلق", "said": "وروي أنه لما قدم نصارى نجران علي رسول - صلى الله عليه وسلم - أتتهم أحبار يهود فتنازعوا عنده، وقال كلا الفريقين للآخر: لستم على شيء، فأنزل الله-عز وجل - هذه الآية، إن قيل: كيف عرض تعالى بتكذيبهم فيما ادعوه وقد صدق الفريقان على قول المسلمين؟ قيل: ليس قول أحد الفريقين بسديد من وجه، إذ قد بتوا الحكم وليس ذلك على البت والقطع، فكلا الفريقين في وقت وعلى وجه على حق، على أن القصد بالآية الدلالة على جهلهم وتخبطهم مع تشاركهم في قراءة التوراة دالة على ما اختلفوا فيه، فبين أن كلا الفريقين حائد عن الطريق، وأنهم في الجهل أو التجاهل كالمشركين الذين لا كتاب لهم في دعواهم على أهل الكتاب والمسلمين أنهم ليسوا على شيء", "en": "It is reported that when the Christians of Najran came to the Prophet ﷺ, the Jewish rabbis came to them and they quarrelled in his presence, each side telling the other, \"you stand on nothing\" — and this verse came down.\nA question: by the Muslims' own view, is each side not now \"on nothing\"? Why does the verse count their words as false? Ar-Raghib: neither statement was right, because each passed an absolute, final verdict — and that is not how it is: each of the two, at one time and in one respect, WAS on the truth. The verse's aim is to show their ignorance and confusion: they both recite the Torah, which points to the answer to what they dispute, yet both have left the road, and in their ignorance — or feigned ignorance — they are like the idolaters with no scripture, who say the same of the People of the Book and the Muslims.\nThen He warned both sides of His judgment between them on the Day of Resurrection, and left that judgment unspecified so that it includes everything said about it: giving the wronged his due from the wrongdoer, showing who denied and who was denied, and \"Hell surrounds the disbelievers\".", "ar": "رُوي أنه لمّا قدم نصارى نجران على رسول الله ﷺ أتتهم أحبار يهود فتنازعوا عنده، وقال كلا الفريقين للآخر: لستم على شيء، فنزلت الآية.\nفإن قيل: على قول المسلمين قد صدق الفريقان، فكيف عرّض بتكذيبهم؟ قال الراغب: لم يكن قول أحدهما سديدًا، لأنهم بتّوا الحكم وليس الأمر على البتّ والقطع، فكلا الفريقين كان في وقتٍ وعلى وجهٍ على حقّ. والقصد بالآية الدلالة على جهلهم وتخبّطهم مع تشاركهم في قراءة التوراة الدالّة على ما اختلفوا فيه: فكلاهما حائدٌ عن الطريق، وهم في الجهل أو التجاهل كالمشركين الذين لا كتاب لهم في دعواهم على أهل الكتاب والمسلمين أنهم ليسوا على شيء.\nثم توعّد الفريقين بحكمه بينهم يوم القيامة، وأبهم الحكم فدخل فيه كلّ ما قيل: إنصاف المظلوم من الظالم، وتمييز المكذِّب من المكذَّب، و﴿وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِٱلۡكَٰفِرِينَ﴾.", "links": [{"ref": "22:17", "q": "﴿إِنَّ ٱللَّهَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ﴾", "en": "Allah Himself will judge between the religions", "ar": "الله يفصل بين أهل الملل يوم القيامة"}, {"ref": "9:49", "q": "﴿وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِٱلۡكَٰفِرِينَ﴾", "en": "One reading of \"He will judge\"", "ar": "أحد وجوه «يحكم بينهم»"}], "v": 1, "p": 296, "pe": 296, "sid": 297},
  {"a": [114, 114], "h": "\"Who is more unjust than one who bars Allah's mosques…\" — and what \"ruining\" a mosque means", "hAr": "﴿وَمَنۡ أَظۡلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ﴾ — ومعنى خراب المساجد", "said": "والأولى بالمساجد أن تكون عامة في كل مكان مرشح للصلاة، فقد قال عليه السلام. \" جعلت لي الأرض مسجدا وطهورا \"، وعظم تعالى ظلم من سعى في المنع من ذكر الله وتخريب الأمكنة المختصة بأهل الشرائع المحقة مسجدا كان أو غير مسجد، وليس التخريب الهدم فقط، بل تعطيله عن عبادة الله- عز وجل-. وقول ابن عباس ومجاهد: إنه عني به الروم إذ خربوا بيت المقدس، وقول غيره إنه عني \" بخت نصر \" لما خربه، وقول من قال: إنما عني به المشركين إذ صدوا النبي عليه السلام عن المسجد الحرام، وكل ذلك أمثلة", "en": "\"Mosques\" is best taken generally: every place made ready for prayer — the Prophet ﷺ said, \"the earth has been made for me a place of prayer and a means of purification\". Allah made grave the wrong of anyone who works to stop the remembrance of Allah and to ruin the places set apart for the followers of true revelations — mosque or not. And ruining is not only demolishing: leaving a place empty of the worship of Allah is ruining it too.\nThe reports — Ibn 'Abbas and Mujahid: the Romans who laid waste to Jerusalem's Holy House; others: Nebuchadnezzar who destroyed it; others: the idolaters who barred the Prophet ﷺ from the Sacred Mosque — are all examples of the ruling and occasions of revelation, not its limits. The proof: He said \"mosques\", in the plural.", "ar": "الأَولى أن تكون «المساجد» عامّةً في كلّ مكانٍ مهيّأٍ للصلاة، فقد قال ﷺ: «جُعلت لي الأرض مسجدًا وطهورًا». وعظّم الله ظلم من سعى في المنع من ذكره وتخريب الأمكنة المختصّة بأهل الشرائع المحقّة، مسجدًا كان أو غير مسجد. وليس التخريب الهدم فقط، بل تعطيلها عن عبادة الله تخريبٌ أيضًا.\nوأقوالهم — ابن عباس ومجاهد: الروم إذ خرّبوا بيت المقدس؛ وغيرهم: بُختنصّر لمّا خرّبه؛ وآخرون: المشركون إذ صدّوا النبي ﷺ عن المسجد الحرام — كلّها أمثلةٌ لحكم الآية وأسبابٌ لنزولها، لا أنه لم يُرد بها غيرها؛ يبيّن ذلك أنه قال «مساجد» بلفظ الجمع.", "links": [{"ref": "22:40", "q": "﴿وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعٞ وَصَلَوَٰتٞ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ كَثِيرٗاۗ﴾", "en": "Places of true worship — \"mosque or not\"", "ar": "أماكن العبادة المحقّة — «مسجدًا كان أو غير مسجد»"}, {"ref": "9:18", "q": "﴿إِنَّمَا يَعۡمُرُ مَسَٰجِدَ ٱللَّهِ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ﴾", "en": "Building a mosque is filling it with worship — its opposite is ruin", "ar": "عمارة المسجد بالعبادة، وضدّها الخراب"}, {"ref": "48:25", "q": "﴿هُمُ ٱلَّذِينَ كَفَرُواْ وَصَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ﴾", "en": "One of the examples: barring from the Sacred Mosque", "ar": "أحد الأمثلة: الصدّ عن المسجد الحرام"}], "v": 1, "p": 297, "pe": 298, "sid": 298},
  {"a": [114, 114], "h": "\"Disgrace in this world\" — including the disgrace people carry inside", "hAr": "﴿لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞ﴾ — ومنه خزيٌ يحملونه في نفوسهم", "said": "وقوله: ﴿مَا كَانَ لَهُمۡ أَن يَدۡخُلُوهَآ إِلَّا خَآئِفِينَۚ﴾ لفظه خبر، ومعناه منطو عليه وعلى الأمر ... ثم ثبت لهم الخزي في الدنيا، وذلك تارة بالهوان الذي يجري عليهم ... وتارة بالهوان الذي يلحقهم في أنفسهم من جبنهم وجزعهم وخوفهم وسائر الآفات النفسية ... وإلى ذلك أشار تعالى بقوله: ﴿وَمَن يُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخۡطَفُهُ ٱلطَّيۡرُ﴾", "en": "\"It was not for them to enter them except in fear\" is worded as a statement, but it carries a command as well: in the lands of Islam, such people are not to be given free run of the houses of Allah, except with permission and for a need.\nTheir \"disgrace in this world\" takes several forms: the humiliation that falls on them from outside — being subdued and losing much of what is open to others, the view of Qatada and others — and the humiliation that lives in their own souls: cowardice, anxiety, fear, restlessness, hearts that never settle on what they chose. That inner ruin is what Allah pictured: \"whoever associates others with Allah, it is as if he fell from the sky and the birds snatch him\".", "ar": "﴿مَا كَانَ لَهُمۡ أَن يَدۡخُلُوهَآ إِلَّا خَآئِفِينَۚ﴾ لفظه خبر، ومعناه منطوٍ على الخبر والأمر: فبيوت الله في دار الإسلام لا يُمكَّن منها أمثالهم إلا بإذنٍ ولحاجةٍ تقتضيه.\nو﴿لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞ﴾: تارةً بالهوان الذي يجري عليهم من خارج — وإليه نظر قتادة وجماعة —، وتارةً بالهوان الذي يلحقهم في أنفسهم: الجبن والجزع والخوف وسائر الآفات النفسية، واضطراب النفوس والقلوب وقلّة سكونها إلى ما اختاروه. وإلى ذلك أشار بقوله: ﴿وَمَن يُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخۡطَفُهُ ٱلطَّيۡرُ﴾.", "links": [{"ref": "22:31", "q": "﴿وَمَن يُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخۡطَفُهُ ٱلطَّيۡرُ أَوۡ تَهۡوِي بِهِ ٱلرِّيحُ فِي مَكَانٖ سَحِيقٖ﴾", "en": "The picture of the inner disgrace", "ar": "صورة الخزي الباطن"}, {"ref": "3:151", "q": "﴿سَنُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ بِمَآ أَشۡرَكُواْ بِٱللَّهِ﴾", "en": "Fear placed in the heart of shirk", "ar": "الرعب في قلوب أهل الشرك"}], "v": 1, "p": 298, "pe": 298, "sid": 299},
  {"a": [115, 115], "h": "\"Wherever you turn, there is the Face of Allah\" — no place holds Him", "hAr": "﴿فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ﴾ — لا يحويه مكان", "said": "المشرق والمغرب تارة يقالان بلفظ الواحد إما إشارة إلى ناحية الأرض، وإما إلى المطلع والمغيب، وتارة بلفظ التثنية إشارة إلى مشرقي ومغربي الشتاء والصيف، وتارة بلفظ الجمع اعتبارا باختلاف المغارب والمطالع كل يوم ... والآية توكيد لما تقدم أنه عني بالمساجد حيث ما صلى فكأنه قيل: لا تعتبروا الأمكنة، فلله- عز وجل- ملك الدنيا، وحيث ما توجهتم فهو موجود يمكنكم الوصول إليه، إذ ليس هو جوهرا ولا عرضا، فيكون بكونه في جانب مفرغا جانبا ونبه بقوله: \" بواسع \" على إحاطته بالأشياء، \" وبالعليم \" أنه لا يخفى عليه خافية", "en": "East and west come in the Quran in three forms: singular — the direction, or the place of rising and setting; dual — the two risings and settings of winter and summer; plural — because the sun rises and sets at a different point every day.\nThe verse confirms what came just before: \"mosques\" means wherever one prays. As if to say: do not make it about places — the whole world is Allah's, and wherever you turn He is there and you can reach Him, for He is not a body or a quality of one, so that being on one side would leave another side empty of Him. \"All-Encompassing\": He surrounds all things; \"All-Knowing\": nothing is hidden from Him.", "ar": "«المشرق والمغرب» يأتيان تارةً بلفظ الواحد — إشارةً إلى الناحية أو إلى المطلع والمغيب —، وتارةً بلفظ التثنية — مشرقا الشتاء والصيف ومغرباهما —، وتارةً بلفظ الجمع — لاختلاف المطالع والمغارب كلّ يوم.\nوالآية توكيدٌ لما قبلها أن «المساجد» حيث ما صُلّي: فكأنه قيل: لا تعتبروا الأمكنة، فلله ملك الدنيا، وحيث ما توجّهتم فهو موجودٌ يمكنكم الوصول إليه، إذ ليس جوهرًا ولا عرضًا فيكون بكونه في جانبٍ مفرغًا جانبًا. ونبّه بـ﴿وَٰسِعٌ﴾ على إحاطته بالأشياء، وبـ﴿عَلِيمٞ﴾ على أنه لا تخفى عليه خافية.", "links": [{"ref": "55:17", "q": "﴿رَبُّ ٱلۡمَشۡرِقَيۡنِ وَرَبُّ ٱلۡمَغۡرِبَيۡنِ﴾", "en": "The dual: winter and summer", "ar": "التثنية: مشرقا الشتاء والصيف"}, {"ref": "70:40", "q": "﴿فَلَآ أُقۡسِمُ بِرَبِّ ٱلۡمَشَٰرِقِ وَٱلۡمَغَٰرِبِ﴾", "en": "The plural: a new rising every day", "ar": "الجمع: مطلعٌ جديد كلّ يوم"}, {"ref": "73:9", "q": "﴿رَّبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ لَآ إِلَٰهَ إِلَّا هُوَ فَٱتَّخِذۡهُ وَكِيلٗا﴾", "en": "The singular", "ar": "الإفراد"}], "v": 1, "p": 298, "pe": 299, "sid": 299},
  {"a": [115, 115], "h": "The verse and the change of the qibla — the views of the Companions", "hAr": "الآية وتحويل القبلة — أقوال الصحابة", "said": "وقد حمل أكثر المفسرين الآية على أنها واردة في القبلة، فمنهم من قال ذلك توطئة لجواز نقلها وتقرير في نفوسهم أن ليس المعبود [سبحانه] في حيز دون حيز، وقيل إن ذلك في زمان كان يجوز الصلاة فيه إلى كل جهة حتى أمروا بقوله: ﴿فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ﴾ وهو قول قتادة وابن زيد، وذلك بعيد لأن القبلة كانت مخصوصة وعلى ذلك قوله ﴿وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ﴾ وقيل إن ذلك في النافلة وجوازها حيث ما توجهت بنا الراحلة، وإليه ذهب ابن عمر، وقيل إن قوما صلوا في ظلمة خفيت عليهم جهة القبلة، فلما أصبحوا كانوا قد صلوا إلى غير القبلة، فأنزل الله - عز وجل- ذلك وإليه ذهب ابن عباس وجماعة", "en": "Most commentators read the verse as being about the qibla, in four ways:\n• It prepared the believers for the qibla's coming change, settling in their hearts that the One they worship is not in one place rather than another.\n• It was for a time when prayer in any direction was allowed, until \"turn your face toward the Sacred Mosque\" came (Qatada, Ibn Zayd) — ar-Raghib calls this far-fetched, since the qibla was always a specific one: \"We did not make the qibla which you used to face…\".\n• It is about voluntary prayer on a riding animal, facing wherever it goes (Ibn 'Umar).\n• Some people prayed in darkness, unable to find the qibla, and in the morning found they had faced the wrong way — and this was revealed (Ibn 'Abbas and others).\nNote how the same words return when the qibla is changed a few pages later: the foolish ask \"what turned them from their qibla?\" and the answer is \"to Allah belong the east and the west\".", "ar": "حمل أكثر المفسّرين الآية على القبلة، على أقوال:\n• أنها توطئةٌ لجواز تحويلها، وتقريرٌ في نفوسهم أن المعبود سبحانه ليس في حيّزٍ دون حيّز.\n• أنها في زمانٍ كانت الصلاة فيه جائزةً إلى كلّ جهةٍ حتى نزل ﴿فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ﴾ — قول قتادة وابن زيد، واستبعده الراغب لأن القبلة كانت مخصوصة: ﴿وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ﴾.\n• أنها في النافلة على الراحلة حيث ما توجّهت — وإليه ذهب ابن عمر.\n• أن قومًا صلّوا في ظلمةٍ خفيت عليهم فيها القبلة، فلمّا أصبحوا إذا هم صلّوا إلى غيرها فنزلت — وإليه ذهب ابن عباس وجماعة.\nولاحظ أن الكلمة نفسها تعود عند تحويل القبلة: ﴿سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ عَلَيۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ﴾.", "links": [{"ref": "2:142", "q": "﴿سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ عَلَيۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ﴾", "en": "The same words answer the objectors when the qibla changes", "ar": "الكلمة نفسها جوابًا للمعترضين عند التحويل"}, {"ref": "2:144", "q": "﴿فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ﴾", "en": "The later command", "ar": "الأمر اللاحق"}, {"ref": "2:177", "q": "﴿لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ﴾", "en": "Righteousness is not the direction itself", "ar": "البرّ ليس في الجهة نفسها"}], "v": 1, "p": 299, "pe": 299, "sid": 300},
  {"a": [116, 116], "h": "Why Allah has no son — the proof from purpose", "hAr": "لماذا لا يكون لله ولد — برهان الغاية", "said": "القنوت: لزوم الطاعة مع الخضوع ... ولما ادعى النصارى في المسيح واليهود في عزير أنهما أبناء الله، ومشركو العرب في الملائكة أنهم بنات الله ... نبه على أقوى حجة على نفي ذلك وبيانها هو أن لكل موجود في العالم مخلوقا طبيعيا أو معمولا صناعيا غرضا وكمالا أوجد لأجله، وإن كان قد يصلح لغيره على سبيل العرض كاليد للبطش، والرجل للمشي، والسكين لقطع مخصوص، والمنشار للنشر ... والغرض في الولد للإنسان إنما هو لأن يبقى به نوعه ... ولما كان الله تعالى هو الباقي الدائم بلا ابتداء ولا انتهاء، لم يكن لاتخاذه الولد لنفسه معنى", "en": "The Christians said it of the Messiah, some Jews of 'Uzayr, and the Arab idolaters called the angels Allah's daughters. Ar-Raghib says the verse points to the strongest proof against all of it:\nEverything that exists — made by nature or by craft — has a purpose it was made for and in which it reaches its completeness, even if it can serve something else in passing: the hand is for grasping, the foot for walking, a knife for a certain kind of cutting, a saw for sawing. The purpose of a child, for a human being, is that his kind should live on through him, a part of him — because Allah gave man no way to last as an individual, He gave him a seed to keep his species. (That is why the sun, the moon and the heavenly bodies were given no seed and no successors: they were not given the perishing of plants and animals.)\nAnd since Allah is the Everlasting, without beginning and without end, taking a child has no meaning for Him at all. Hence \"Glory be to Him!\" — He is far above the very cause that makes a child needed.", "ar": "ادّعى النصارى في المسيح، واليهود في عزير أنهما ابنا الله، ومشركو العرب في الملائكة أنهم بنات الله؛ فنبّه — كما يقول الراغب — على أقوى حجّةٍ في نفي ذلك:\nلكلّ موجودٍ في العالم — مخلوقًا طبيعيًّا أو معمولًا صناعيًّا — غرضٌ وكمالٌ أُوجد لأجله، وإن صلح لغيره على سبيل العَرَض: كاليد للبطش، والرجل للمشي، والسكين لقطعٍ مخصوص، والمنشار للنشر. والغرض من الولد للإنسان أن يبقى به نوعه، وهو جزءٌ منه، لأن الله لم يجعل له سبيلًا إلى البقاء بشخصه، فجعل له بذرًا يحفظ نوعه؛ ولهذا لم يجعل للشمس والقمر وسائر الأجرام السماوية بذرًا ولا استخلافًا، إذ لم يجعل لها فناء النبات والحيوان.\nولمّا كان الله هو الباقي الدائم بلا ابتداءٍ ولا انتهاء، لم يكن لاتخاذه الولد معنى؛ ولهذا قال ﴿سُبۡحَٰنَهُۥۖ﴾: منزّهٌ عن السبب المقتضي للولد.", "links": [{"ref": "6:101", "q": "﴿بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٞ وَلَمۡ تَكُن لَّهُۥ صَٰحِبَةٞۖ﴾", "en": "The same argument in al-An'am", "ar": "الحجّة نفسها في الأنعام"}, {"ref": "9:30", "q": "﴿وَقَالَتِ ٱلۡيَهُودُ عُزَيۡرٌ ٱبۡنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى ٱلۡمَسِيحُ ٱبۡنُ ٱللَّهِۖ﴾", "en": "The two claims named", "ar": "الدعويان مسمّاتان"}], "v": 1, "p": 300, "pe": 300, "sid": 301},
  {"a": [116, 116], "h": "\"To Him belongs all\" and \"all are devoted to Him\" — the second and third proofs", "hAr": "﴿لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ﴾ و﴿كُلّٞ لَّهُۥ قَٰنِتُونَ﴾ — الحجّتان الثانية والثالثة", "said": "ثم لما كان اقتناء الولد لفقر ما، وذلك لما تقدم أن الإنسان افتقر إلى نسل يخلفه لكونه غير كامل في نفسه، بين تعالى بقوله ﴿لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ﴾ أنه لا يتوهم له فقر فيه فيحتاج إلى اتخاذ ما هو سد لفقره ... وهو أنه لما كان الولد يعتقد فيه خدمة الأب ومظاهرته كما قال: ﴿وَجَعَلَ لَكُم مِّنۡ أَزۡوَٰجِكُم بَنِينَ وَحَفَدَةٗ﴾، بين أن كل ما في السماوات والأرض مع كونه ملكا له فقانت له أيضا إما طائعا، وإما كارها، وإما مسخرا، كقوله: ﴿وَلِلَّهِۤ يَسۡجُدُۤ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا﴾، وقوله: ﴿وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ﴾، وهذا أبلغ حجة لمن هو على المحجة", "en": "Second proof: people seek children out of some need — a human needs offspring to succeed him because he is not complete in himself. \"To Him belongs whatever is in the heavens and the earth\" shows that no need can even be imagined in Him, that He should acquire something to fill it.\nThird proof, in \"all are devoted to Him\": a son is expected to serve his father and stand by him — \"He made for you, from your spouses, sons and grandsons\". But everything in the heavens and the earth, besides being His property, is devoted to Him already — willingly, unwillingly, or simply made to serve: \"to Allah bows whoever is in the heavens and the earth, willingly or unwillingly\", \"there is nothing but glorifies Him with praise\". What would a son add? \"The most eloquent proof, for whoever is on the clear road.\"\nQunut itself is keeping to obedience with humility — so it is explained by either word (\"stand before Allah devoutly\"); and since standing still is part of its completeness, the Prophet ﷺ, asked which prayer is best, said \"long qunut\" — long standing.", "ar": "الحجّة الثانية: اقتناء الولد لفقرٍ ما، فالإنسان افتقر إلى نسلٍ يخلفه لأنه غير كاملٍ في نفسه؛ فبيّن بقوله ﴿لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ﴾ أنه لا يُتوهّم له فقرٌ فيحتاج إلى ما يسدّه.\nوالثالثة في ﴿قَٰنِتُونَ﴾: لمّا كان الولد يُرجى منه خدمة الأب ومظاهرته — ﴿وَجَعَلَ لَكُم مِّنۡ أَزۡوَٰجِكُم بَنِينَ وَحَفَدَةٗ﴾ —، بيّن أن كلّ ما في السماوات والأرض، مع كونه ملكًا له، قانتٌ له أيضًا: طائعًا أو كارهًا أو مسخّرًا، كقوله: ﴿وَلِلَّهِۤ يَسۡجُدُۤ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا﴾، و﴿وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ﴾. «وهذا أبلغ حجّةٍ لمن هو على المحجّة».\nو«القنوت» لزوم الطاعة مع الخضوع، ولذا فُسّر بكلٍّ منهما في ﴿وَقُومُواْ لِلَّهِ قَٰنِتِينَ﴾؛ ولمّا كان القيام والسكون من تمامه استُعمل فيهما، فلمّا سُئل ﷺ: أيّ الصلاة أفضل؟ قال: «طول القنوت» أي القيام.", "links": [{"ref": "10:68", "q": "﴿قَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗاۗ سُبۡحَٰنَهُۥۖ هُوَ ٱلۡغَنِيُّۖ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ﴾", "en": "The second proof stated outright: \"He is the Self-Sufficient\"", "ar": "الحجّة الثانية مصرّحًا بها: {هو الغني}"}, {"ref": "13:15", "q": "﴿وَلِلَّهِۤ يَسۡجُدُۤ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا﴾", "en": "Devoted willingly or unwillingly", "ar": "القنوت طوعًا وكرهًا"}, {"ref": "17:44", "q": "﴿وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ﴾", "en": "Everything already glorifies Him", "ar": "كلّ شيءٍ يسبّح بحمده"}, {"ref": "2:238", "q": "﴿وَقُومُواْ لِلَّهِ قَٰنِتِينَ﴾", "en": "Qunut in prayer", "ar": "القنوت في الصلاة"}], "v": 1, "p": 300, "pe": 301, "sid": 301},
  {"a": [116, 116], "h": "Where the error came from — the word \"Father\"", "hAr": "من أين دخلت الشبهة — لفظ «الأب»", "said": "إن قيل: من أين وقع لهم الشبهة في نسبة الولد إلى الله تعالى؟ قيل: قد ذكر أن في الشرائع المتقدمة كانوا يطلقون على البارئ تعالى اسم \" الأب \"، وعلى الكبير منهم اسم الإله ... وكانوا يريدون بذلك أنه تعالى هو السبب الأول في وجود الإنسان، وأن الأب هو السبب الأخير في وجوده ... ثم تصور الجهلة منهم باخرة معنى الولادة الطبيعية، فصار ذلك منهيا عن التفوه به في شرعنا تنزها عن هذا الاعتقاد، حتى صار إطلاقه وإن قصد به ما قصده هؤلاء قرين الكفر", "en": "How did such an idea arise? Ar-Raghib reports that in earlier revealed laws people used to call the Creator \"Father\", and even called their great men \"god\" — meaning that Allah is the first cause of a person's existence and the father the last cause, and that a father is \"served\" by his son in a sense. They meant something sound, as our own scholars say Allah \"loves and is loved\", and as people say \"king of kings\". So 'Isa could say, \"I am going to my Father\".\nThen, later, the ignorant among them imagined natural begetting. So our law forbade the word altogether, to stay far from that belief — until using it, even meaning what those early people meant, became a companion of disbelief.", "ar": "من أين وقعت لهم الشبهة؟ ذكر الراغب أنه كان في الشرائع المتقدّمة يُطلق على البارئ تعالى اسم «الأب»، وعلى الكبير منهم اسم «الإله»، يريدون أنه تعالى السبب الأوّل في وجود الإنسان، وأن الأب السبب الأخير، وأن الأب «مخدوم» الابن من وجه؛ وكانوا يقصدون معنًى صحيحًا، كما يقول علماؤنا: الله محبٌّ ومحبوب، ومريدٌ ومراد، وكما يُقال: «ملك الملوك». ومن ذلك قول عيسى: «أنا ذاهبٌ إلى أبي».\nثم تصوّر الجهلة منهم بأَخَرةٍ معنى الولادة الطبيعية، فصار التفوّه به منهيًّا عنه في شرعنا تنزّهًا عن هذا الاعتقاد، حتى صار إطلاقه — وإن قُصد به ما قصده أولئك — قرين الكفر.", "links": [{"ref": "5:18", "q": "﴿وَقَالَتِ ٱلۡيَهُودُ وَٱلنَّصَٰرَىٰ نَحۡنُ أَبۡنَٰٓؤُاْ ٱللَّهِ وَأَحِبَّٰٓؤُهُۥۚ﴾", "en": "The word taken literally — and refuted", "ar": "اللفظ حين أُخذ على ظاهره، ورُدّ"}, {"ref": "9:30", "q": "﴿يُضَٰهِـُٔونَ قَوۡلَ ٱلَّذِينَ كَفَرُواْ مِن قَبۡلُۚ﴾", "en": "Copying the words of those before them", "ar": "مضاهاة قول من قبلهم"}], "v": 1, "p": 301, "pe": 301, "sid": 302},
  {"a": [117, 117], "h": "\"Originator of the heavens and the earth\" — the fourth proof, and Allah's three kinds of making", "hAr": "﴿بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ﴾ — الحجّة الرابعة، وأنواع فعل الله الثلاثة", "said": "البديع: يقال للمبدع والمبدع جميعا، والإبداع إيجاد فعل ابتداء لا احتذاء، ولهذا قيل: فلان بدع في كذا، وجعل البدعة اسما لكل مخترع لم يؤثر عن أرباب الشرع ... ذكره تعالى هذه الآية حجة رابعة شرحها أن الأب هو عنصر للابن، منه تكون، والله مبدع الأشياء كلها، فلا يكون عنصرا للولد، فمن المحال أن يكون المنفعل فاعلا، وخص لفظ الإبداع لكونه أبلغ لفظا وأبعده عن الاحتمال، وذلك أن أفعال الله تعالى على ثلاثة أوجه: إبداع وهو \" اختراع \" الشيء لا عن شيء ولا في زمان، ويستعمل ذلك في إيجاده تعالى المبادئ، و \" صنع \" وهو تركيب صورة مع العنصر، وتستعمل في إيجاده الأجسام، و \" تسخير \" وهو سوق الشيء إلى غرضه المقصود منه طوعا أو قهرا، ويستعمل في القوى التي أوجدها في السحاب والأمطار والأغذية والأدوية، وكل هذه الثلاثة يقال له الخلق، وأقدمها الإبداع", "en": "Ibda' is bringing something into being from the very start, not by copying — which is why a bid'ah is the name for any invention not handed down from the founders of the religion.\nFourth proof: a father is the source-matter of his son — the son is formed from him. Allah is the Originator of all things, so He cannot be matter for a child: what is acted upon cannot be the Actor.\nHe chose the word \"Originator\" because it is the strongest and least open to misreading. Allah's acts are of three kinds: origination — inventing a thing from nothing and not in time, used of His bringing the first principles into being; making — joining a form to matter, used of bodies; and subjecting — driving a thing to the purpose it was made for, willingly or by force, used of the powers He placed in clouds, rain, foods and medicines. All three are called \"creation\", and the first of them is origination.", "ar": "«البديع» يُقال للمبدِع والمبدَع جميعًا، و«الإبداع» إيجاد الفعل ابتداءً لا احتذاءً، ولهذا جُعلت «البدعة» اسمًا لكلّ مخترَعٍ لم يؤثَر عن أرباب الشرع.\nوالحجّة الرابعة: الأب عنصرٌ للابن، منه يتكوّن؛ والله مبدع الأشياء كلّها، فلا يكون عنصرًا لولد، فمن المحال أن يكون المنفعل فاعلًا.\nوخصّ لفظ الإبداع لأنه أبلغ لفظًا وأبعده عن الاحتمال: فأفعال الله ثلاثة: «إبداع» — اختراع الشيء لا عن شيءٍ ولا في زمان، في إيجاده المبادئ —، و«صنع» — تركيب صورةٍ مع عنصر، في إيجاده الأجسام —، و«تسخير» — سوق الشيء إلى غرضه المقصود منه طوعًا أو قهرًا، في القوى التي أودعها السحاب والأمطار والأغذية والأدوية. وكلّها يُقال لها «الخلق»، وأقدمها الإبداع.", "links": [{"ref": "6:101", "q": "﴿بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٞ وَلَمۡ تَكُن لَّهُۥ صَٰحِبَةٞۖ وَخَلَقَ كُلَّ شَيۡءٖۖ﴾", "en": "\"Originator\" again as the answer to \"a son\"", "ar": "«البديع» مرّةً أخرى جوابًا لدعوى الولد"}, {"ref": "14:33", "q": "﴿وَسَخَّرَ لَكُمُ ٱلشَّمۡسَ وَٱلۡقَمَرَ دَآئِبَيۡنِۖ﴾", "en": "Subjecting (taskhir)", "ar": "التسخير"}], "v": 1, "p": 302, "pe": 302, "sid": 303},
  {"a": [117, 117], "h": "\"Be — and it is\": the fifth proof, and why the words are a picture", "hAr": "﴿كُن فَيَكُونُ﴾: الحجّة الخامسة، ولماذا الألفاظ تصويرٌ لنا", "said": "والقضاء: إتمام الشيء قولا أو فعلا، فمن القول قوله تعالى: ﴿وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ﴾، ﴿وَقَضَيۡنَآ إِلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ فِي ٱلۡكِتَٰبِ﴾، ومن الفعل قوله: ﴿فَقَضَىٰهُنَّ سَبۡعَ سَمَٰوَاتٖ فِي يَوۡمَيۡنِ﴾ ... ونبه بقوله: ﴿قَضَىٰٓ أَمۡرٗا﴾ على حجة خامسة، وهو أن الولد يكون بنشر وتركيب حالا بعد حال، وهو إذا أراد شيئا فقد فعل بلا مهلة ولم يرد \" بإذا \" حقيقة الزمان، إذ كان ذلك إشارة إلى ما قبل وجود الزمان، ولم يرد أيضا \" بكن \" حقيقة اللفظ ولا بالفاء التعقيب الزماني، بل استعير كل ذلك لأنه أقرب ما يتراءى لنا به سرعة الفعل وتمامه", "en": "Qada' is completing a thing, by word or by deed: by word — \"your Lord has decreed that you worship none but Him\"; by deed — \"He completed them as seven heavens in two days\".\nFifth proof, in \"when He decrees a matter\": a child comes by growth and composition, stage after stage; but when Allah wills a thing, it is done without delay.\nAnd none of the words are meant literally: \"when\" is not real time, since it points to what is before time existed; \"Be\" is not a real sound; the \"and\" of \"and it is\" is not a sequence in time. All of it is borrowed, because it is the nearest picture we can grasp of how swift and complete His act is. \"Decree\" was chosen because it means completing; \"say\" because speech is the lightest and quickest thing we produce; \"Be\" for its all-embracing meaning and brevity; \"and it is\" to show that nothing He wills can refuse to be. \"Be, and it is\" looks like two things, one after the other, but it is really one — as we say of someone, \"when he wanted something, it was as he wanted\".", "ar": "«القضاء» إتمام الشيء قولًا أو فعلًا: فمن القول ﴿وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ﴾، ومن الفعل ﴿فَقَضَىٰهُنَّ سَبۡعَ سَمَٰوَاتٖ فِي يَوۡمَيۡنِ﴾.\nوالحجّة الخامسة في ﴿وَإِذَا قَضَىٰٓ أَمۡرٗا﴾: الولد يكون بنشرٍ وتركيبٍ حالًا بعد حال، والله إذا أراد شيئًا فقد فعل بلا مهلة.\nولم يُرد بـ«إذا» حقيقة الزمان — فذلك إشارةٌ إلى ما قبل وجود الزمان —، ولا بـ«كن» حقيقة اللفظ، ولا بالفاء التعقيب الزمانيّ؛ بل استُعير ذلك كلّه لأنه أقرب ما يتراءى لنا به سرعة الفعل وتمامه: فذكر «القضاء» لأنه إتمام الفعل، و«القول» لأنه أخفّ ما يوجَد منّا وأسرعه، و«كن» لعموم معناه واختصار لفظه، و﴿فَيَكُونُ﴾ تنبيهًا أنه لا يمتنع عليه شيءٌ يريده. و«كن فيكون» وإن خرج مخرج شيئين أحدهما مبنيٌّ على الآخر فهو في الحقيقة شيءٌ واحد، كقولنا: فلانٌ إذا أراد شيئًا فقد كان ما أراد.", "links": [{"ref": "19:35", "q": "﴿مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٖۖ سُبۡحَٰنَهُۥٓۚ إِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ﴾", "en": "The same pairing — \"no son\" with \"Be, and it is\" — in Maryam", "ar": "الاقتران نفسه — نفي الولد مع «كن فيكون» — في مريم"}, {"ref": "36:82", "q": "﴿إِنَّمَآ أَمۡرُهُۥٓ إِذَآ أَرَادَ شَيۡـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ﴾", "en": "\"His command, when He wills a thing\"", "ar": "«إنما أمره إذا أراد شيئًا»"}, {"ref": "54:50", "q": "﴿وَمَآ أَمۡرُنَآ إِلَّا وَٰحِدَةٞ كَلَمۡحِۭ بِٱلۡبَصَرِ﴾", "en": "One act, like the blink of an eye", "ar": "أمرٌ واحد كلمح البصر"}], "v": 1, "p": 302, "pe": 302, "sid": 303},
  {"a": [118, 118], "h": "Certainty — and hearts that resemble each other across the ages", "hAr": "اليقين — وقلوبٌ تتشابه عبر الأزمان", "said": "اليقين أبلغ علم وأوكده، وهو أن تكون عالما بالشئ، وعالما بأنك تعلمه غير شاك ولا متهيئ للشك، ولذلك قيل: هو المعلوم الذي زالت عنه المعارضة على مرور الأوقات، وإنما لم يوصف الباري تعالى به من حيث أنه لا يستعمل إلا في العلم المكتسب ... ثم بين أنهم متشابهون في العمي والجهالة، لاقتراحهم على رسلهم كقوله: ﴿أَتَوَاصَوۡاْ بِهِۦۚ بَلۡ هُمۡ قَوۡمٞ طَاغُونَ﴾", "en": "Certainty (yaqin) is the strongest, firmest knowledge: to know a thing, and to know that you know it, without doubting and without being open to doubt — \"knowledge from which every objection has fallen away over time\". It is never used of Allah, because it is said only of knowledge that is acquired — which is why it is said of Ibrahim, \"thus We showed Ibrahim the kingdom of the heavens and the earth, that he might be of those with certainty\".\n\"Those who do not know\" — the Jews (Ibn 'Abbas), the Christians (Mujahid), or the Arab idolaters (al-Hasan, Qatada). All are possible, and all may be meant: the People of the Book asked for \"a book from the sky\", and the idolaters said \"we will not believe you until you make a spring gush from the earth for us\". \"Those before them\" are the earlier disbelieving nations: Musa's people said \"show us Allah openly\", 'Isa's disciples asked for a table from the sky.\n\"Their hearts are alike\": the same blindness, the same habit of dictating terms to their messengers — as if they had handed it down to one another: \"did they bequeath it to each other? No — they are a transgressing people.\"", "ar": "«اليقين» أبلغ العلم وأوكده: أن تكون عالمًا بالشيء، وعالمًا بأنك تعلمه، غير شاكٍّ ولا متهيّئٍ للشكّ؛ ولذلك قيل: هو المعلوم الذي زالت عنه المعارضة على مرور الأوقات. ولم يوصف به البارئ تعالى لأنه لا يُستعمل إلا في العلم المكتسَب؛ ولهذا قال في إبراهيم: ﴿وَكَذَٰلِكَ نُرِيٓ إِبۡرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلِيَكُونَ مِنَ ٱلۡمُوقِنِينَ﴾.\nو﴿ٱلَّذِينَ لَا يَعۡلَمُونَ﴾: اليهود (ابن عباس)، أو النصارى (مجاهد)، أو مشركو العرب (الحسن وقتادة) — وكلّه محتمل، ويصحّ أن يكونوا جميعًا مرادين: فأهل الكتاب سألوا ﴿أَن تُنَزِّلَ عَلَيۡهِمۡ كِتَٰبٗا مِّنَ ٱلسَّمَآءِۚ﴾، ومشركو العرب قالوا: ﴿لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ ٱلۡأَرۡضِ يَنۢبُوعًا﴾. و﴿ٱلَّذِينَ مِن قَبۡلِهِم﴾: كافرو الأمم السابقة: قال أصحاب موسى ﴿أَرِنَا ٱللَّهَ جَهۡرَةٗ﴾، وسأل أصحاب عيسى المائدة.\nو﴿تَشَٰبَهَتۡ قُلُوبُهُمۡۗ﴾: في العمى والجهالة واقتراحهم على رسلهم، كقوله: ﴿أَتَوَاصَوۡاْ بِهِۦۚ بَلۡ هُمۡ قَوۡمٞ طَاغُونَ﴾.", "links": [{"ref": "6:75", "q": "﴿وَكَذَٰلِكَ نُرِيٓ إِبۡرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلِيَكُونَ مِنَ ٱلۡمُوقِنِينَ﴾", "en": "Certainty is acquired — even by Ibrahim", "ar": "اليقين مكتسَب — حتى لإبراهيم"}, {"ref": "17:90", "q": "﴿لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ ٱلۡأَرۡضِ يَنۢبُوعًا﴾", "en": "The idolaters' demands", "ar": "اقتراحات المشركين"}, {"ref": "4:153", "q": "﴿فَقَالُوٓاْ أَرِنَا ٱللَّهَ جَهۡرَةٗ﴾", "en": "Musa's people before them", "ar": "قوم موسى قبلهم"}, {"ref": "51:53", "q": "﴿أَتَوَاصَوۡاْ بِهِۦۚ بَلۡ هُمۡ قَوۡمٞ طَاغُونَ﴾", "en": "\"Their hearts are alike\"", "ar": "«تشابهت قلوبهم»"}], "v": 1, "p": 303, "pe": 304, "sid": 304},
  {"a": [118, 118], "h": "\"We have made the signs clear\" — why a demanded miracle was not given", "hAr": "﴿قَدۡ بَيَّنَّا ٱلۡأٓيَٰتِ﴾ — لماذا لم تُعطَ الآية المقترَحة", "said": "إن قيل: إنهم وإن أخطأوا في قولهم: ﴿لَوۡلَا يُكَلِّمُنَا ٱللَّهُ﴾ فإنهم لم يخطئوا في سؤال الآية، إذ لا يلزم الإنسان أن يؤمن إلا لمن يأتي بآية تدل على صدقه، قيل: إنما أنكر عليهم جحودهم الأيات التي آتاهم، ولذلك قال ﴿قَدۡ بَيَّنَّا ٱلۡأٓيَٰتِ﴾ ... وقوله: ﴿لِقَوۡمٖ يُوقِنُونَ﴾ فيه معنيان: أحدهما أنهم يطلبون اليقين وليس بهم المعاندة، والثاني: أن من حصل له اليقين بالحق المحض وليس يعتريه شبهة فله في القرآن لا آية بل آيات ... ومن قال: هلا أجابهم إلى سؤالهم ... فسؤال جاهل بحكمة الله تعالى", "en": "A fair question: they were wrong to say \"why does Allah not speak to us\", but were they wrong to ask for a sign? No one has to believe a man unless he brings a sign of his truth. Ar-Raghib: what is condemned is their denial of the signs already given — hence \"We HAVE made the signs clear\", as elsewhere: \"they say, 'why are signs not sent down to him?' Say: the signs are with Allah… Is it not enough for them that We sent down to you the Book, recited to them?\"\n\"For a people who have certainty\" has two senses: people who seek certainty, with no stubbornness in them; and whoever has reached certainty in the pure truth, free of doubt, finds in the Quran not one sign but many — \"for those who believe it is guidance and healing\".\nAnd to ask \"why did He not just grant their demand?\" is to be ignorant of Allah's wisdom: the Wise does not act against wisdom at the dictation of the ignorant, and He had already removed every excuse without their demand — \"if the truth followed their desires, the heavens and the earth and all in them would be ruined\".", "ar": "فإن قيل: أخطؤوا في قولهم ﴿لَوۡلَا يُكَلِّمُنَا ٱللَّهُ﴾، فهل أخطؤوا في سؤال الآية، والإنسان لا يلزمه أن يؤمن إلا لمن أتى بآيةٍ تدلّ على صدقه؟ قال الراغب: إنما أنكر عليهم جحودهم الآيات التي آتاهم؛ ولذلك قال ﴿قَدۡ بَيَّنَّا ٱلۡأٓيَٰتِ﴾، كقوله: ﴿وَقَالُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَٰتٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِ﴾ ثم ﴿أَوَلَمۡ يَكۡفِهِمۡ أَنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ يُتۡلَىٰ عَلَيۡهِمۡۚ﴾.\nو﴿لِقَوۡمٖ يُوقِنُونَ﴾ فيه معنيان: قومٌ يطلبون اليقين وليست بهم معاندة؛ أو من حصل له اليقين بالحقّ المحض فلا تعتريه شبهة، فله في القرآن لا آيةٌ بل آيات، كما قال: ﴿قُلۡ هُوَ لِلَّذِينَ ءَامَنُواْ هُدٗى وَشِفَآءٞۚ﴾.\nومن قال: هلّا أجابهم إلى سؤالهم؟ فسؤال جاهلٍ بحكمة الله: فالحكيم لا يفعل ما ينافي الحكمة باقتراح جاهل، وقد أزاح العلّة بغير ما سألوا، وإلى ذلك أشار بقوله: ﴿وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَآءَهُمۡ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ﴾.", "links": [{"ref": "29:51", "q": "﴿أَوَلَمۡ يَكۡفِهِمۡ أَنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ يُتۡلَىٰ عَلَيۡهِمۡۚ﴾", "en": "The sign already given: the Book itself", "ar": "الآية المعطاة: الكتاب نفسه"}, {"ref": "41:44", "q": "﴿قُلۡ هُوَ لِلَّذِينَ ءَامَنُواْ هُدٗى وَشِفَآءٞۚ﴾", "en": "Not one sign but many, for those with certainty", "ar": "لا آيةٌ بل آيات لأهل اليقين"}, {"ref": "23:71", "q": "﴿وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَآءَهُمۡ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ﴾", "en": "Why demands are not obeyed", "ar": "لماذا لا تُجاب الاقتراحات"}], "v": 1, "p": 304, "pe": 304, "sid": 305},
  {"a": [119, 119], "h": "\"A bringer of good news and a warner\" — the Prophet ﷺ is not answerable for those who refuse", "hAr": "﴿بَشِيرٗا وَنَذِيرٗاۖ﴾ — ليس على النبي ﷺ حساب من أبى", "said": "فبين تعالى أن عليك البشارة والإنذار، ولا يلزمك عقابهم تسلية له، كقوله: ﴿فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَيۡهِمۡ حَسَرَٰتٍۚ﴾، وقوله ﴿لَّيۡسَ عَلَيۡكَ هُدَىٰهُمۡ﴾، وقوله: ﴿مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُۗ﴾. وقوله: ﴿فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ وَعَلَيۡنَا ٱلۡحِسَابُ﴾ ... وقرأ نافع (ولا تسئل)، بالجزم، فقيل ذلك تفخيما لشأنهم، وقيل: نهى عن تتبع ما أغناه الله عنه من أخبار من مضى", "en": "Jahim is the fiercely blazing fire. Allah tells His Prophet: yours is to give good news and to warn — their punishment is not laid on you. It is a consolation, like \"do not let your soul waste away in grief over them\", \"their guidance is not your responsibility\", \"the Messenger's only duty is to convey\", \"yours is only to convey, and Ours is the reckoning\".\nNafi' read it as a prohibition — \"and do not ask about the people of Hellfire\" — either to show how dreadful their state is, too terrible to ask about; or forbidding him to chase after news of past peoples that Allah had spared him from needing.", "ar": "«الجحيم» النار المتأجّجة. فبيّن تعالى: عليك البشارة والإنذار، ولا يلزمك عقابهم — تسليةً له ﷺ، كقوله: ﴿فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَيۡهِمۡ حَسَرَٰتٍۚ﴾، و﴿لَّيۡسَ عَلَيۡكَ هُدَىٰهُمۡ﴾، و﴿مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُۗ﴾، و﴿فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ وَعَلَيۡنَا ٱلۡحِسَابُ﴾.\nوقرأ نافع بالجزم على النهي — أي: لا تسألْ أنت عنهم —: فقيل: تفخيمًا لشأنهم — حالهم أفظع من أن يُسأل عنها —، وقيل: نهيٌ عن تتبّع ما أغناه الله عنه من أخبار من مضى.", "links": [{"ref": "35:8", "q": "﴿فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَيۡهِمۡ حَسَرَٰتٍۚ﴾", "en": "Do not grieve yourself to death over them", "ar": "لا تذهب نفسك عليهم حسرات"}, {"ref": "13:40", "q": "﴿فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ وَعَلَيۡنَا ٱلۡحِسَابُ﴾", "en": "Yours to convey, Ours the reckoning", "ar": "عليك البلاغ وعلينا الحساب"}, {"ref": "33:45", "q": "﴿يَٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدٗا وَمُبَشِّرٗا وَنَذِيرٗا﴾", "en": "The same mission named again", "ar": "المهمّة نفسها"}], "v": 1, "p": 305, "pe": 305, "sid": 306},
  {"a": [120, 120], "h": "Millah and din — and why desire is called a god", "hAr": "الملّة والدين — ولماذا سُمّي الهوى إلهًا", "said": "الملة: من أمللت الكتاب، وهي اسم لما شرعه الله تعالي لعباده على لسان أنبيائه ليتوصلوا به إلي آجل ثوابه، والدين ملة، لكن الملة تقال باعتبار دعا الله وإنزال كتبه والدين باعتبار طاعة العباد له بإجابة دعائه والانقياد لأمره، والشيء الواحد قد يسمى باسمين على اعتبارين ... والهوى: رأي عن شهوة داع إلى الضلال وسمي بذلك لأنه يهوي بصاحبه في الدنيا إلى كل داهية، وفي الآخرة إلى الهاوية، ولهذا سميت النار هاوية، ولشدة سلطانه وصفه الله بأنه إله الكفار، فقال: ﴿أَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ﴾", "en": "Millah comes from \"amlaltu al-kitab\", \"I dictated the writing\": it is the name for what Allah laid down for His servants on the tongues of His prophets, so that through it they reach His reward to come. Din is the same thing, seen from the other side: millah is the religion as Allah's call and His revealed books; din is the religion as the servants' obedience — answering His call and yielding to His command. One thing, two names, two angles. (Only by extension are the words used for systems not from Allah.)\nHawa, desire, is an opinion born of appetite that calls to error. It is called hawa because it makes its owner fall (yahwi) into every disaster in this world, and into the Pit (al-hawiyah) in the next — hence the Fire is called Hawiyah. And because its power over people is so great, Allah described it as the god of the disbelievers: \"have you seen him who takes his own desire as his god?\"", "ar": "«الملّة» من «أمللتُ الكتاب»: اسمٌ لما شرعه الله لعباده على ألسنة أنبيائه ليتوصّلوا به إلى آجل ثوابه. و«الدين» هو الملّة، لكن الملّة تُقال باعتبار دعاء الله وإنزال كتبه، والدين باعتبار طاعة العباد له بإجابة دعائه والانقياد لأمره؛ فالشيء الواحد قد يُسمّى باسمين على اعتبارين. (وقد يُقالان توسّعًا لما لم يكن من عند الله.)\nو«الهوى» رأيٌ عن شهوةٍ داعٍ إلى الضلال، وسُمّي بذلك لأنه يهوي بصاحبه في الدنيا إلى كلّ داهية، وفي الآخرة إلى الهاوية — ولهذا سُمّيت النار هاوية —؛ ولشدّة سلطانه وصفه الله بأنه إله الكفّار: ﴿أَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ﴾.", "links": [{"ref": "45:23", "q": "﴿أَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ﴾", "en": "Desire as a god", "ar": "الهوى إلهًا"}, {"ref": "101:8-9", "q": "﴿وَأَمَّا مَنۡ خَفَّتۡ مَوَٰزِينُهُۥ ۝ فَأُمُّهُۥ هَاوِيَةٞ﴾", "en": "Where desire makes one fall", "ar": "حيث يهوي الهوى بصاحبه"}], "v": 1, "p": 305, "pe": 306, "sid": 306},
  {"a": [120, 120], "h": "\"If you followed their desires…\" — the closer one is, the stricter the account", "hAr": "﴿وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم﴾ — كلّما عظم القرب عظمت المؤاخذة", "said": "ومعنى الآية أن من خالفوك لا يرضون عنك إلا بمتابعة ملتهم تنبيها أنه لا يرضيهم إلا ما لا يجوز وقوعه منك ... ثم حذره فقال: ﴿وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم﴾، وذلك تحذير له ولأمته، ولكن خص بالذكر لأن أنبياء الله ، بل أولياءه بأدنى ميل إلى ضال يكونون في حكم تابعي هواهم ... فإن من حصل له زلفة متناهية من السلطان لا يتجافى عما يقع منه من أدنى مخالفة كالتجافي عن الأجانب ... وإنما قال: أهواءهم بلفظ الجمع تنبيها على أن لكل هوى غير هوى الأخر، ثم هوى كل واحد منهم لا يتناهى", "en": "\"They will never be pleased with you until you follow their creed\": a hint that nothing will please them except what can never come from you. Then \"Allah's guidance is the guidance\" — not following them.\nWhy is the Prophet ﷺ himself warned, \"if you followed their desires…\", when it is a warning for his whole community? Because Allah's prophets — and even His close friends — with the slightest leaning toward the misguided are counted as following their desires, and are held to account for what others are not. People know this from life: one who has reached the utmost nearness to a king is not excused the smallest breach, as strangers would be. Hence the sayings: \"the great sins of the friends of Allah are the small sins of ordinary people\", and \"the indecency of the friends of Allah is slackness in guarding their every breath\".\n\"Desires\", plural: each of them has a desire different from the other's, and each one's desire has no end. The Quran warns against desire as such: \"do not follow desire, lest it lead you astray from the path of Allah\".", "ar": "﴿وَلَن تَرۡضَىٰ عَنكَ ٱلۡيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ﴾: تنبيهٌ أنه لا يرضيهم إلا ما لا يجوز وقوعه منك. ثم بيّن أن اتّباعهم ليس بهدى: ﴿قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۗ﴾.\nثم حذّره: ﴿وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم﴾ — والتحذير له ولأمّته، وخُصّ بالذكر لأن أنبياء الله، بل أولياءه، بأدنى ميلٍ إلى ضالٍّ يكونون في حكم تابعي هواه، ويؤاخَذون بما لا يؤاخَذ به غيرهم؛ وذلك معروفٌ في التعارف: من بلغ زلفةً متناهيةً من السلطان لا يُتجافى عن أدنى مخالفةٍ منه كما يُتجافى عن الأجانب. ولهذا قيل: «كبائر الأولياء صغائر العوامّ»، وقيل: «فاحشة الأولياء التواني في تعهّد الأنفاس».\nوقال ﴿أَهۡوَآءَهُم﴾ بالجمع تنبيهًا على أن لكلٍّ هوًى غير هوى الآخر، ثم هوى كلّ واحدٍ لا يتناهى. وهو تحذيرٌ من الهوى جملةً: ﴿وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ﴾.", "links": [{"ref": "6:56", "q": "﴿قُل لَّآ أَتَّبِعُ أَهۡوَآءَكُمۡ قَدۡ ضَلَلۡتُ إِذٗا وَمَآ أَنَا۠ مِنَ ٱلۡمُهۡتَدِينَ﴾", "en": "The Prophet's own answer", "ar": "جواب النبي ﷺ نفسه"}, {"ref": "5:77", "q": "﴿وَلَا تَتَّبِعُوٓاْ أَهۡوَآءَ قَوۡمٖ قَدۡ ضَلُّواْ مِن قَبۡلُ﴾", "en": "The same warning to the believers", "ar": "التحذير نفسه للمؤمنين"}, {"ref": "38:26", "q": "﴿وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ﴾", "en": "Desire as such", "ar": "الهوى جملةً"}, {"ref": "17:75", "q": "﴿إِذٗا لَّأَذَقۡنَٰكَ ضِعۡفَ ٱلۡحَيَوٰةِ وَضِعۡفَ ٱلۡمَمَاتِ﴾", "en": "The nearer, the stricter the account", "ar": "كلّما عظم القرب عظمت المؤاخذة"}], "v": 1, "p": 306, "pe": 306, "sid": 307},
  {"a": [121, 121], "h": "\"They recite it as it should be recited\" — reading, understanding, living it", "hAr": "﴿يَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ﴾ — قراءةً وفهمًا وعملًا", "said": "قد تقدم الكلام في التلاوة، منها تكون بالقراءة تارة، وبتتبع المعنى تارة، وباستعمال مقتضاه تارة، وهو المعنى بقوله: ﴿حَقَّ تِلَاوَتِهِۦٓ﴾، وعليه دل قول ابن عباس وابن مسعود يتبعونه حق اتباعه، وقول مجاهد \" يعملون به حق عمله \"، وقول عمر: \" حق تلاوته \": إذا ذكر الجنة سأل الله الجنة، وإذا ذكر النار تعوذ منها \"، وذلك عام في كتاب الله تعالى وفي أربابها ... ونحو ذلك قوله تعالى: ﴿وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَآءٞ وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارٗا﴾، وهذه الأية كالتحقيق لما تقدم من قوله: ﴿وَقَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ لَوۡلَا يُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِينَآ ءَايَةٞۗ﴾", "en": "Tilawah is of three kinds: reading the words; following the meaning; and doing what it requires. The last is \"reciting it as it should be recited\": Ibn 'Abbas and Ibn Mas'ud — \"they follow it as it truly should be followed\"; Mujahid — \"they act on it as it should be acted on\"; 'Umar — \"when he comes to Paradise he asks Allah for Paradise, and when he comes to the Fire he seeks refuge from it\".\nIt holds for every book of Allah and its people: Qatada said the Companions, Ibn Zayd the People of the Book, others the Arabs who accepted Islam — all are included, as the general wording requires. They are the ones who gain faith through it; those who deny it gain only loss: \"We send down of the Quran what is healing and mercy for the believers, and it increases the wrongdoers only in loss\".\nAnd this verse answers the one a few lines earlier — \"why does Allah not speak to us, or a sign come to us?\": Allah HAS spoken; the Book is there, and those who recite it truly find it.", "ar": "«التلاوة» تكون بالقراءة تارة، وبتتبّع المعنى تارة، وباستعمال مقتضاه تارة — وهو المعنيّ بـ﴿حَقَّ تِلَاوَتِهِۦٓ﴾: وعليه دلّ قول ابن عباس وابن مسعود: «يتّبعونه حقّ اتّباعه»، وقول مجاهد: «يعملون به حقّ عمله»، وقول عمر: «إذا ذكر الجنة سأل الله الجنة، وإذا ذكر النار تعوّذ منها».\nوذلك عامٌّ في كتب الله وأربابها: فقول قتادة «أصحاب النبي ﷺ»، وقول ابن زيد «أهل الكتاب»، وقول غيرهما «من أسلم من العرب» — كلّه داخلٌ فيه، وعموم اللفظ يقتضيه. وهم الذين يحصل لهم الإيمان به، دون المنكرين الذين ليس لهم إلا الخسران: ﴿وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَآءٞ وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارٗا﴾.\nوهذه الآية كالتحقيق لقوله قبلُ: ﴿وَقَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ لَوۡلَا يُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِينَآ ءَايَةٞۗ﴾: قد كلّمهم الله، والكتاب بين أيديهم، ومن تلاه حقّ تلاوته وجده.", "links": [{"ref": "2:118", "q": "﴿وَقَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ لَوۡلَا يُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِينَآ ءَايَةٞۗ﴾", "en": "The demand this verse answers", "ar": "الطلب الذي تجيب عنه الآية"}, {"ref": "38:29", "q": "﴿كِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ مُبَٰرَكٞ لِّيَدَّبَّرُوٓاْ ءَايَٰتِهِۦ﴾", "en": "Reciting means reflecting", "ar": "التلاوة تدبّر"}, {"ref": "17:82", "q": "﴿وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَآءٞ وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارٗا﴾", "en": "Healing for some, loss for others", "ar": "شفاءٌ لقومٍ وخسارٌ لآخرين"}], "v": 1, "p": 307, "pe": 307, "sid": 308},
  {"a": [122, 123], "h": "Why these two verses are repeated — and why the order changes", "hAr": "لماذا تكرّرت الآيتان — ولماذا تغيّر الترتيب", "said": "ويسأل عن فائدة تكريرها، وأنه قال في هذه الآية: ﴿وَلَا يُقۡبَلُ مِنۡهَا عَدۡلٞ وَلَا تَنفَعُهَا شَفَٰعَةٞ﴾ وفي الآية المتقدمة قال: ﴿وَلَا يُقۡبَلُ مِنۡهَا شَفَٰعَةٞ وَلَا يُؤۡخَذُ مِنۡهَا عَدۡلٞ﴾، والجواب: أما التكرير فعلى سبيل الإنذار، فالواعظ إذا وعظ لأمر ما قد يكرر الذي يعظ لأجله تعظيما لأمره، وأما تغيير النظم، فلما كان قبول العدل وأخذه وقبول الشفاعة ونفعها متلازمة، لم يكن بين اتفاق هذه العبارات واختلافها فرق في المعنى", "en": "These two verses came almost word for word at 2:47–48. Why repeat them? Because repetition belongs to warning: a preacher who warns about something repeats it, to show how serious it is.\nAnd why \"no compensation will be accepted, nor intercession benefit\" here, when earlier it was \"no intercession will be accepted, nor compensation taken\"? Because accepting a ransom and taking it, accepting intercession and its benefiting, go together — so whether the wording is the same or different, the meaning does not change.", "ar": "تقدّم مضمون الآيتين (٤٧–٤٨)، ويُسأل عن فائدة تكريرهما، وعن قوله هنا: ﴿وَلَا يُقۡبَلُ مِنۡهَا عَدۡلٞ وَلَا تَنفَعُهَا شَفَٰعَةٞ﴾، وقبلُ: ﴿وَلَا يُقۡبَلُ مِنۡهَا شَفَٰعَةٞ وَلَا يُؤۡخَذُ مِنۡهَا عَدۡلٞ﴾.\nوالجواب: التكرير على سبيل الإنذار، فالواعظ إذا وعظ لأمرٍ كرّر ما يعظ لأجله تعظيمًا لشأنه. وأمّا تغيير النظم: فلمّا كان قبول العدل وأخذه، وقبول الشفاعة ونفعها، متلازمةً، لم يكن بين اتّفاق العبارات واختلافها فرقٌ في المعنى.", "links": [{"ref": "2:47", "q": "﴿يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ﴾", "en": "The same words opened the address to the Children of Israel; here they close it, just before Ibrahim", "ar": "الكلمات نفسها افتُتح بها خطاب بني إسرائيل، وبها يُختم قبل قصّة إبراهيم"}, {"ref": "2:48", "q": "﴿وَلَا يُقۡبَلُ مِنۡهَا شَفَٰعَةٞ وَلَا يُؤۡخَذُ مِنۡهَا عَدۡلٞ﴾", "en": "The first wording", "ar": "الصيغة الأولى"}], "v": 1, "p": 308, "pe": 308, "sid": 309},
  {"a": [124, 124], "h": "\"Ibrahim was tested with words, and he fulfilled them\"", "hAr": "﴿وَإِذِ ٱبۡتَلَىٰٓ إِبۡرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتٖ فَأَتَمَّهُنَّۖ﴾", "said": "الابتلاء كالاختبار، لكن الابتلاء طلب إظهار الفعل، والاختبار طلب الخبر، وهما متلازمان ... والكلمات التي ابتلى بها مبهمة محتملة، وذكر المفسرون لها وجوها يصح أن تكون كلها مراده، فقيل: هي عشر سنن ... وقيل: هي خصال محمودة ذكر بعضها في سورة/ التوبة، وبعضها في سورة/ المؤمنون، وبعضها في سورة/ سأل سائل ... وقيل: هي مناسك الحج ... وقيل: امتحانه بإنفاق ماله، وهجر أوطانه، وذبح ولده، وإلقائه في النار فلما لم يؤثر على اختبار الله في شيء من ذلك قال فيه: (فأتمهن) وإتمامه: هو الوفاء بها المذكور في قوله: ﴿وَإِبۡرَٰهِيمَ ٱلَّذِي وَفَّىٰٓ﴾", "en": "Ibtila' and ikhtibar both mean testing, but ibtila' seeks to bring out the deed, ikhtibar to bring out the knowledge — and each goes with the other.\nThe \"words\" he was tested with are left unnamed, and ar-Raghib says all the commentators' answers may be meant together:\n• ten practices of the natural way — five in the head (rinsing the mouth, the nose, parting the hair, trimming the moustache, the siwak) and five in the body (clipping nails, the armpits, circumcision, shaving, cleaning oneself);\n• praiseworthy qualities listed in at-Tawbah, al-Mu'minun and al-Ma'arij;\n• the rites of Hajj;\n• (these three from Ibn 'Abbas);\n• the star, the moon and the sun;\n• giving up his wealth, leaving his homeland, being asked to sacrifice his son, being thrown into the fire.\nAnd since in none of it did he hold anything back from Allah, He said \"and he fulfilled them\" — the fulfilment praised elsewhere: \"and Ibrahim, who fulfilled\".", "ar": "«الابتلاء» كالاختبار، لكن الابتلاء طلب إظهار الفعل، والاختبار طلب الخبر، وهما متلازمان.\nو«الكلمات» مبهمةٌ محتملة، وذكر المفسّرون لها وجوهًا يصحّ أن تكون كلّها مرادة:\n• عشر سُنن: خمسٌ في الرأس — المضمضة والاستنشاق والفَرق وقصّ الشارب والسواك —، وخمسٌ في الجسد — تقليم الأظفار ونتف الإبط والختان وحلق العانة والاستنجاء؛\n• خصالٌ محمودة ذُكر بعضها في التوبة، وبعضها في المؤمنون، وبعضها في المعارج؛\n• مناسك الحجّ المذكورة في ﴿وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ﴾ — وكلّ ذلك عن ابن عباس؛\n• ابتلاؤه بالكوكب والقمر والشمس؛\n• امتحانه بإنفاق ماله، وهجر وطنه، وذبح ولده، وإلقائه في النار.\nفلمّا لم يؤثر على الله شيئًا من ذلك قال: ﴿فَأَتَمَّهُنَّۖ﴾ — وإتمامه هو الوفاء المذكور في ﴿وَإِبۡرَٰهِيمَ ٱلَّذِي وَفَّىٰٓ﴾.", "links": [{"ref": "53:37", "q": "﴿وَإِبۡرَٰهِيمَ ٱلَّذِي وَفَّىٰٓ﴾", "en": "\"He fulfilled them\"", "ar": "«فأتمّهن»"}, {"ref": "9:112", "q": "﴿ٱلتَّٰٓئِبُونَ ٱلۡعَٰبِدُونَ ٱلۡحَٰمِدُونَ ٱلسَّٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّٰجِدُونَ﴾", "en": "The qualities in at-Tawbah", "ar": "الخصال في التوبة"}, {"ref": "22:26", "q": "﴿وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ﴾", "en": "The rites of Hajj", "ar": "مناسك الحج"}, {"ref": "37:103", "q": "﴿فَلَمَّآ أَسۡلَمَا وَتَلَّهُۥ لِلۡجَبِينِ﴾", "en": "The hardest test: his son", "ar": "أشدّ الابتلاء: ولده"}, {"ref": "21:69", "q": "﴿قُلۡنَا يَٰنَارُ كُونِي بَرۡدٗا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ﴾", "en": "The fire", "ar": "النار"}], "v": 1, "p": 308, "pe": 310, "sid": 309},
  {"a": [124, 124], "h": "\"An imam for all people\" — why every prophet after him came from his line", "hAr": "﴿إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامٗاۖ﴾ — ولماذا كان الأنبياء بعده من ذرّيته", "said": "وفي إطلاق الشرع اسم للمقتدي به، المقتدي بالشرع، وهو أعم من النبي والخليفة إذ كل نبي وخليفة: إمام ... وجعل إمامته للناس كافة على التأبيد، فإنه لم يبعث بعده نبي إلا من ذريته، كما قال تعالى: ﴿وَجَعَلۡنَا فِي ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَ﴾، وقال: ﴿وَجَعَلَهَا كَلِمَةَۢ بَاقِيَةٗ فِي عَقِبِهِۦ﴾ حتى قال للنبي (محمد) عليه السلام: ﴿ثُمَّ أَوۡحَيۡنَآ إِلَيۡكَ أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۖ﴾ ... ولم يرد بالإمامة ههنا النبوة كما ظنه بعض المفسرين، فإنه- عليه السلام- إمام للناس على العموم في كل زمان على الإطلاق وليس بنبي لهم على [العموم] بالإطلاق ... لكنه تعالى بين أنه قد يكون من ذريته ظالم، وبين أن الإمام يتحمل للعهد، والظالم لا عهد له، فإذا لا إمامة له", "en": "An imam is, in origin, anyone who is followed, rightly or wrongly — \"the Day We call every people by their imam\", \"We made them leaders calling to the Fire\". In the language of the law it is one who is followed and who himself follows the law. It is wider than \"prophet\" or \"caliph\": every prophet and caliph is an imam.\nAllah made Ibrahim an imam for all people, for all time: no prophet was sent after him except from his descendants — \"We placed prophethood and the Book among his offspring\", \"He made it a word lasting among his descendants\" — until He said to Muhammad ﷺ, \"then We revealed to you: follow the religion of Ibrahim, upright\". The Prophet ﷺ even taught us to mention Ibrahim in the prayer: \"O Allah, send blessings on Muhammad and the family of Muhammad as You sent blessings on Ibrahim.\"\nThis imamate is not prophethood, as some thought: he is an imam for all people in every age, but he was not a prophet sent to them all. \"And of my offspring?\" — \"My covenant does not reach the wrongdoers\": there may be wrongdoers among his offspring, and an imam carries a covenant; a wrongdoer has no covenant, so he has no imamate.", "ar": "«الإمام» في الأصل المؤتمّ به محقًّا كان أو مبطلًا: ﴿يَوۡمَ نَدۡعُواْ كُلَّ أُنَاسِۭ بِإِمَٰمِهِمۡۖ﴾، ﴿وَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَدۡعُونَ إِلَى ٱلنَّارِۖ﴾؛ وفي إطلاق الشرع: المقتدى به المقتدي بالشرع، وهو أعمّ من النبيّ والخليفة، إذ كلّ نبيٍّ وخليفةٍ إمام.\nوجعل إمامة إبراهيم للناس كافّةً على التأبيد، فلم يُبعث بعده نبيٌّ إلا من ذرّيته: ﴿وَجَعَلۡنَا فِي ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَ﴾، ﴿وَجَعَلَهَا كَلِمَةَۢ بَاقِيَةٗ فِي عَقِبِهِۦ﴾، حتى قال لنبيّنا ﷺ: ﴿ثُمَّ أَوۡحَيۡنَآ إِلَيۡكَ أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۖ﴾، و﴿مِّلَّةَ أَبِيكُمۡ إِبۡرَٰهِيمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِينَ مِن قَبۡلُ﴾، وأمرنا ﷺ بذكر إبراهيم في الصلاة: «اللهم صلِّ على محمدٍ وعلى آل محمد كما صلّيت على إبراهيم».\nولم يُرد بالإمامة هنا النبوّة كما ظنّ بعض المفسّرين: فهو إمامٌ للناس عمومًا في كلّ زمان، وليس نبيًّا لهم جميعًا. و﴿وَمِن ذُرِّيَّتِيۖ﴾ فأُجيب: ﴿لَا يَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ﴾ — قد يكون من ذرّيته ظالم، والإمام متحمّلٌ للعهد، والظالم لا عهد له، فلا إمامة له.", "links": [{"ref": "29:27", "q": "﴿وَجَعَلۡنَا فِي ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَ﴾", "en": "Prophethood kept in his line", "ar": "النبوّة في ذرّيته"}, {"ref": "43:28", "q": "﴿وَجَعَلَهَا كَلِمَةَۢ بَاقِيَةٗ فِي عَقِبِهِۦ﴾", "en": "A word lasting among his descendants", "ar": "كلمةٌ باقية في عقبه"}, {"ref": "16:123", "q": "﴿ثُمَّ أَوۡحَيۡنَآ إِلَيۡكَ أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۖ﴾", "en": "Muhammad ﷺ told to follow him", "ar": "أُمر نبيّنا ﷺ باتّباع ملّته"}, {"ref": "22:78", "q": "﴿مِّلَّةَ أَبِيكُمۡ إِبۡرَٰهِيمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِينَ مِن قَبۡلُ﴾", "en": "The name \"Muslims\" from him", "ar": "اسم «المسلمين» من قبل"}], "v": 1, "p": 309, "pe": 310, "sid": 310},
  {"a": [125, 125], "h": "\"A place of return for people, and security\" — a ruling, and a sign", "hAr": "﴿مَثَابَةٗ لِّلنَّاسِ وَأَمۡنٗا﴾ — حكمٌ وآية", "said": "والمثابة إما لثؤوب الناس إليه، وإما لاستحقاقهم الثواب بقصده ... بين تعالى أنه جعل البيت من حيث الحكم مثابة للناس وأمنا ومصلى، ولم يعن أنهم ملجؤون إلى أن لا يخيفوا أحدا، كما لم يعن أنهم ملجؤون إلى أن يجعلوه مصلى ومثابة ... على أن حكم الله في ذلك مما فيه آية منه لأنه حض الناس على استعظام البيت ... ومن ضيعها كان ممقوتا غير منفك من عقوبة إما متجلية للمناظر أو ظاهرة لأولي البصائر", "en": "Mathabah, \"a place of return\", either because people keep returning (tha'aba) to it, or because they earn reward (thawab) by setting out for it. (And if some who go have never been before, it is a place of \"return\" for humankind as a whole, not for each individual.)\n\"And security\": Allah made the House, as a RULING, a place of return, of security and of prayer. He did not mean that people are forced by nature never to frighten anyone there — just as they are not forced to make it a place of prayer. It is a command laid on people. The same holds for \"whoever enters it is safe\" and \"have they not seen that We made a secure sanctuary, while people are snatched away all around them?\"\nYet the ruling is itself a sign from Allah: He moved people to such reverence for the House that ordinary people do not dare to violate it, and whoever violated its sanctity was hated and did not escape punishment — either plain for the eyes to see, or clear to those with insight.", "ar": "«المثابة»: إمّا لثؤوب الناس إليه — رجوعهم —، وإمّا لاستحقاقهم الثواب بقصده. (وإن كان من قاصديه من لم يأته قبلُ، فهو مثابةٌ باعتبار جنس الناس لا آحادهم.)\nو﴿وَأَمۡنٗا﴾: جعل الله البيت من حيث الحكم مثابةً وأمنًا ومصلًّى، ولم يعنِ أنهم مُلجَؤون إلى ألّا يُخيفوا فيه أحدًا، كما لم يعنِ أنهم ملجؤون إلى أن يجعلوه مصلًّى؛ فهو حكمٌ وأمر. وعلى ذلك ﴿وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ﴾ و﴿أَوَلَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنٗا وَيُتَخَطَّفُ ٱلنَّاسُ مِنۡ حَوۡلِهِمۡۚ﴾.\nعلى أن حكم الله في ذلك فيه آيةٌ منه: فقد حضّ الناس على استعظام البيت حتى لا تجسر عامّتهم على انتهاك حرمته، ومن ضيّعها كان ممقوتًا غير منفكٍّ من عقوبة، إمّا ظاهرةٍ للنواظر، أو بيّنةٍ لأولي البصائر.", "links": [{"ref": "3:97", "q": "﴿فِيهِ ءَايَٰتُۢ بَيِّنَٰتٞ مَّقَامُ إِبۡرَٰهِيمَۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ﴾", "en": "\"Whoever enters it is safe\" — the same ruling", "ar": "{ومن دخله كان آمنا} — الحكم نفسه"}, {"ref": "29:67", "q": "﴿أَوَلَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنٗا وَيُتَخَطَّفُ ٱلنَّاسُ مِنۡ حَوۡلِهِمۡۚ﴾", "en": "Security as a visible sign", "ar": "الأمن آيةٌ مشهودة"}, {"ref": "5:97", "q": "﴿جَعَلَ ٱللَّهُ ٱلۡكَعۡبَةَ ٱلۡبَيۡتَ ٱلۡحَرَامَ قِيَٰمٗا لِّلنَّاسِ﴾", "en": "The House as a pillar for people", "ar": "البيت قيامٌ للناس"}], "v": 1, "p": 311, "pe": 312, "sid": 312},
  {"a": [125, 125], "h": "\"Take the station of Ibrahim as a place of prayer\" — and what \"purify My House\" includes", "hAr": "﴿وَٱتَّخِذُواْ مِن مَّقَامِ إِبۡرَٰهِـۧمَ مُصَلّٗىۖ﴾ — وما يدخل في ﴿طَهِّرَا بَيۡتِيَ﴾", "said": "ومقام إبراهيم الحرم عن ابن عباس، والمزدلفة عن عطاء، والحجر عن السدى، والأولى أنه الحرم كله ... وروي فيه أن النبي - صلى الله عليه وسلم - قال لعمر لما انتهى إلى المقام: \" هذا مقام أبينا إبراهيم، [فقال: ألا نتخذه مصلى؟] \" فأنزل الله- عز وجل- ﴿وَٱتَّخِذُواْ مِن مَّقَامِ إِبۡرَٰهِـۧمَ مُصَلّٗىۖ﴾ ... ﴿وَعَهِدۡنَآ إِلَىٰٓ﴾ أي، أمرناهما أمرا موثقا عليهما بأن يطهرا البيت من الأنجاس والشرك وكل ما ينافي موضع الطهارة، للطائفين: أي القصاد، وقيل لأولي الطواف، وكلاهما مراد، والركع السجود: المصلين، وقيل: قد دخل في الأمر بتطهيره أن يبنيانه على تقوى كما قال: ﴿أَفَمَنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ تَقۡوَىٰ مِنَ ٱللَّهِ وَرِضۡوَٰنٍ خَيۡرٌ﴾", "en": "The \"station of Ibrahim\": the whole sanctuary (Ibn 'Abbas), Muzdalifah ('Ata'), or the Stone (as-Suddi); ar-Raghib prefers the whole sanctuary — every place they named is a place of prayer and supplication.\nRead as a command, as in our Mushaf, it is linked to the report that the Prophet ﷺ said to 'Umar when they reached the Station, \"This is the station of our father Ibrahim\", and 'Umar asked, \"Shall we not take it as a place of prayer?\" — and Allah revealed: \"and take the station of Ibrahim as a place of prayer\".\n\"We charged Ibrahim and Isma'il\": a binding command, to purify the House of filth, of shirk, and of everything unfit for a place of purity — for \"those who circle it\" (those who come to it, or those who perform tawaf; both are meant) and \"those who bow and prostrate\" (those who pray). And it is said that purifying it includes building it on God-consciousness: \"is one who founded his building on fear of Allah and His pleasure better…?\"", "ar": "«مقام إبراهيم»: الحرم (ابن عباس)، أو المزدلفة (عطاء)، أو الحِجر (السدّي)، والأَولى أنه الحرم كلّه، فما من موضعٍ ذكروه إلا وهو مصلًّى — موضع دعاءٍ أو صلاة.\nوقُرئ ﴿وَٱتَّخِذُواْ﴾ على الأمر، ورُوي أن النبي ﷺ قال لعمر لمّا انتهى إلى المقام: «هذا مقام أبينا إبراهيم»، فقال عمر: ألا نتّخذه مصلًّى؟ فأنزل الله: ﴿وَٱتَّخِذُواْ مِن مَّقَامِ إِبۡرَٰهِـۧمَ مُصَلّٗىۖ﴾.\nو﴿وَعَهِدۡنَآ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ﴾: أمرناهما أمرًا موثّقًا أن يطهّرا البيت من الأنجاس والشرك وكلّ ما ينافي موضع الطهارة، ﴿لِلطَّآئِفِينَ﴾ — القُصّاد، أو أهل الطواف، وكلاهما مراد —، ﴿وَٱلرُّكَّعِ ٱلسُّجُودِ﴾ — المصلّين. وقيل: دخل في الأمر بتطهيره أن يبنياه على تقوى، كما قال: ﴿أَفَمَنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ تَقۡوَىٰ مِنَ ٱللَّهِ وَرِضۡوَٰنٍ خَيۡرٌ﴾.", "links": [{"ref": "9:109", "q": "﴿أَفَمَنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ تَقۡوَىٰ مِنَ ٱللَّهِ وَرِضۡوَٰنٍ خَيۡرٌ﴾", "en": "Purity of the foundation", "ar": "طهارة الأساس"}, {"ref": "22:26", "q": "﴿وَطَهِّرۡ بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ﴾", "en": "The same charge in al-Hajj", "ar": "العهد نفسه في الحج"}, {"ref": "9:28", "q": "﴿إِنَّمَا ٱلۡمُشۡرِكُونَ نَجَسٞ فَلَا يَقۡرَبُواْ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ بَعۡدَ عَامِهِمۡ هَٰذَاۚ﴾", "en": "Purified of shirk", "ar": "التطهير من الشرك"}], "v": 1, "p": 311, "pe": 312, "sid": 312}
];
